import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-advanced-l3-001', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'What is PostGIS and what geometry types does it provide?', options: ['PostGIS is a PostgreSQL extension for spatial and geographic data — it adds geometry types (POINT, LINESTRING, POLYGON, MULTIPOINT, etc.), spatial functions, and spatial indexing, enabling storage and analysis of location-based data directly in the database', 'PostGIS is a geographic information system application', 'PostGIS is a map rendering engine', 'PostGIS is a GPS tracking tool'], correctAnswer: 0, explanation: 'PostGIS extends PostgreSQL with spatial data types conforming to the OGC Simple Features specification. The geometry type stores planar (flat-earth) coordinates, while geography type handles spheroidal (round-earth) coordinates. PostGIS supports 2D, 3D (Z), and 4D (ZM) geometries. It includes thousands of spatial functions for analysis, transformation, and measurement.', codeSnippet: "CREATE EXTENSION postgis;\n\n-- Geometry types:\nCREATE TABLE places (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  location GEOMETRY(Point, 4326),\n  boundary GEOMETRY(Polygon, 4326),\n  route GEOMETRY(LineString, 4326)\n);\n\n-- Insert a point (longitude, latitude):\nINSERT INTO places (name, location)\nVALUES ('Eiffel Tower',\n  ST_SetSRID(ST_MakePoint(2.2945, 48.8584), 4326));\n\n-- Geography type (spheroidal calculations):\nCREATE TABLE cities (\n  name TEXT,\n  location GEOGRAPHY(Point, 4326)\n);", tags: ['advanced', 'postgis', 'geometry-types', 'spatial'] },
  { id: 'pg-advanced-l3-002', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How does ST_Distance work in PostGIS?', options: ['ST_Distance measures time between events', 'ST_Distance returns the minimum distance between two geometries — for geometry type it returns Cartesian distance in the unit of the SRID, for geography type it returns the great-circle distance in meters, accounting for Earth curvature', 'ST_Distance calculates network distance', 'ST_Distance counts rows between two records'], correctAnswer: 1, explanation: 'ST_Distance is the most commonly used measurement function. With geometry type, it calculates planar distance (fast but inaccurate for geographic coordinates). With geography type, it calculates geodesic distance using the WGS84 spheroid (slower but accurate). For SRID 4326 (WGS84) geometry, distances are in degrees which are not useful for real-world measurement — use geography type or ST_Transform to a projected CRS.', codeSnippet: "-- Distance between two points (geography = meters):\nSELECT ST_Distance(\n  ST_MakePoint(2.2945, 48.8584)::geography,  -- Paris\n  ST_MakePoint(-73.9857, 40.7484)::geography  -- NYC\n) / 1000 AS km;\n-- Result: ~5837 km\n\n-- Distance between geometry points (SRID units):\nSELECT ST_Distance(\n  ST_GeomFromText('POINT(0 0)'),\n  ST_GeomFromText('POINT(3 4)')\n); -- 5.0 (Cartesian)\n\n-- Find nearest restaurants within 500m:\nSELECT name,\n  ST_Distance(location, my_location) AS dist_m\nFROM restaurants\nWHERE ST_DWithin(location, my_location, 500)\nORDER BY location <-> my_location\nLIMIT 10;", tags: ['advanced', 'postgis', 'st-distance', 'measurement'] },
  { id: 'pg-advanced-l3-003', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'What does ST_Within do in PostGIS?', options: ['ST_Within checks if a timestamp is within a range', 'ST_Within checks if a value is within a numeric range', 'ST_Within returns true if geometry A is completely inside geometry B — meaning every point of A is inside B and their boundaries do not touch, commonly used for point-in-polygon queries like finding which district a location belongs to', 'ST_Within checks if a string is within another string'], correctAnswer: 2, explanation: 'ST_Within(A, B) returns TRUE if geometry A is completely contained within geometry B. The inverse is ST_Contains(B, A). These functions are fundamental for spatial queries like "which buildings are in this flood zone?" or "which delivery zone does this address belong to?". ST_Within uses the DE-9IM spatial relationship model. For performance, always use a spatial index with ST_Within.', codeSnippet: "-- Is point within polygon?\nSELECT ST_Within(\n  ST_MakePoint(2.3, 48.9)::geometry,\n  ST_GeomFromText(\n    'POLYGON((2.2 48.8, 2.4 48.8, 2.4 49.0,\n             2.2 49.0, 2.2 48.8))'\n  )\n); -- true\n\n-- Find which district a point belongs to:\nSELECT d.name AS district\nFROM districts d\nWHERE ST_Within(\n  ST_SetSRID(ST_MakePoint(2.3522, 48.8566), 4326),\n  d.boundary\n);\n\n-- Find all stores in a delivery zone:\nSELECT s.name, s.address\nFROM stores s\nJOIN delivery_zones dz ON ST_Within(s.location, dz.area)\nWHERE dz.name = 'Zone A';", tags: ['advanced', 'postgis', 'st-within', 'containment'] },
  { id: 'pg-advanced-l3-004', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you create a spatial index in PostGIS?', options: ['Use a B-tree index on the geometry column', 'Use a hash index on the geometry column', 'Use CREATE INDEX ... USING GiST on the geometry column — GiST (Generalized Search Tree) indexes use bounding box comparisons to quickly filter spatial data, and are essential for any spatial query involving operators like && (bounding box overlap), ST_Within, ST_Intersects, or <-> (KNN distance)', 'Spatial indexes are created automatically'], correctAnswer: 3, explanation: 'GiST indexes are the standard spatial index type in PostGIS. They index bounding boxes (rectangles that enclose geometries), enabling fast spatial filtering. The query planner first uses the index to find geometries whose bounding boxes intersect, then applies the exact geometry test. This two-step process (filter + refine) is fundamental to spatial query performance. SP-GiST and BRIN indexes are alternatives for specific use cases.', codeSnippet: "-- Create GiST spatial index:\nCREATE INDEX idx_places_location\n  ON places USING gist (location);\n\n-- For geography columns:\nCREATE INDEX idx_cities_location\n  ON cities USING gist (location);\n\n-- Verify index usage:\nEXPLAIN ANALYZE\nSELECT * FROM places\nWHERE ST_DWithin(\n  location,\n  ST_SetSRID(ST_MakePoint(2.3, 48.9), 4326),\n  1000\n);\n-- Index Scan using idx_places_location\n\n-- KNN uses the index for ordering:\nSELECT name, location <-> ST_MakePoint(2.3, 48.9)::geometry\nFROM places\nORDER BY location <-> ST_MakePoint(2.3, 48.9)::geometry\nLIMIT 5;\n-- Index Scan (KNN) using idx_places_location", tags: ['advanced', 'postgis', 'spatial-index', 'gist'] },
  { id: 'pg-advanced-l3-005', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'What is the difference between geometry and geography types in PostGIS?', options: ['Geometry is 2D, geography is 3D', 'Geometry is for points, geography is for polygons', 'They are identical types with different names', 'Geometry uses flat-plane Cartesian math (fast but inaccurate for large areas on Earth), while geography uses spheroidal calculations on the WGS84 ellipsoid (slower but accurate for real-world distances) — geometry needs a projected CRS for accurate measurements'], correctAnswer: 0, explanation: 'The geometry type treats coordinates as points on a flat plane, making calculations fast but meaningless for geographic coordinates (degrees) over large distances. The geography type uses geodesic calculations accounting for Earth curvature, giving accurate distances in meters but supporting fewer functions and being slower. For small areas, use geometry with a local projected CRS (like UTM). For global data, use geography.', codeSnippet: "-- Geometry: fast, but degrees are not meters!\nSELECT ST_Distance(\n  ST_GeomFromText('POINT(0 0)', 4326),\n  ST_GeomFromText('POINT(1 1)', 4326)\n); -- 1.414 (degrees, not meters!)\n\n-- Geography: slower, but accurate meters:\nSELECT ST_Distance(\n  'SRID=4326;POINT(0 0)'::geography,\n  'SRID=4326;POINT(1 1)'::geography\n); -- 156899 meters (~157 km)\n\n-- Convert for accurate local calculations:\nSELECT ST_Distance(\n  ST_Transform(a.geom, 32632),  -- UTM zone 32N\n  ST_Transform(b.geom, 32632)\n) AS distance_meters\nFROM points a, points b;\n\n-- Geography supports fewer functions:\n-- ST_Buffer, ST_Intersection need geometry\n-- Cast when needed:\nSELECT ST_Buffer(location::geometry, 0.01)\nFROM cities;", tags: ['advanced', 'postgis', 'geometry-vs-geography', 'crs'] },
  { id: 'pg-advanced-l3-006', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'What is the pgcrypto extension in PostgreSQL?', options: ['pgcrypto provides cryptographic functions for PostgreSQL — including hashing (digest, crypt), symmetric encryption (pgp_sym_encrypt/decrypt), public-key encryption (pgp_pub_encrypt/decrypt), and random data generation (gen_random_bytes, gen_random_uuid)', 'pgcrypto is a cryptocurrency payment processor', 'pgcrypto manages SSL/TLS certificates', 'pgcrypto encrypts the entire database'], correctAnswer: 1, explanation: 'pgcrypto brings cryptographic capabilities directly into SQL queries and PL/pgSQL functions. It supports multiple hash algorithms (MD5, SHA-1, SHA-256, SHA-512), password hashing with bcrypt (crypt/gen_salt), symmetric encryption (AES, Blowfish via PGP), and public-key encryption (RSA via PGP). gen_random_uuid() (now built-in since PG 13) and gen_random_bytes() generate cryptographically secure random data.', codeSnippet: "CREATE EXTENSION pgcrypto;\n\n-- SHA-256 hash:\nSELECT digest('hello', 'sha256');\n-- Returns bytea, encode for hex:\nSELECT encode(digest('hello', 'sha256'), 'hex');\n\n-- Bcrypt password hashing:\nSELECT crypt('mypassword', gen_salt('bf', 10));\n-- $2a$10$xxxxx...\n\n-- Verify password:\nSELECT crypt('mypassword', stored_hash) = stored_hash;\n-- true if password matches\n\n-- Random bytes:\nSELECT gen_random_bytes(16); -- 16 random bytes\nSELECT gen_random_uuid();    -- random UUID v4", tags: ['advanced', 'pgcrypto', 'encryption', 'hashing'] },
  { id: 'pg-advanced-l3-007', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you securely hash passwords with pgcrypto?', options: ['Use MD5 hashing for passwords', 'Use SHA-256 for password storage', 'Use the crypt() function with gen_salt("bf") for bcrypt — bcrypt is a password-specific hash that includes a configurable work factor (cost), automatic salt generation, and is designed to be slow to resist brute-force attacks', 'Store passwords in plain text with AES encryption'], correctAnswer: 2, explanation: 'crypt() with bcrypt (bf) is the recommended password hashing approach. Unlike general-purpose hashes (MD5, SHA-256), bcrypt is deliberately slow and includes a cost factor that can be increased as hardware improves. gen_salt("bf", cost) generates a salt with the specified work factor (default 8, recommended 10-12). The salt is embedded in the hash, so no separate salt storage is needed.', codeSnippet: "-- Hash a password with bcrypt:\nINSERT INTO users (name, password_hash)\nVALUES (\n  'alice',\n  crypt('s3cretP@ss', gen_salt('bf', 12))\n);\n\n-- Verify a password:\nSELECT id, name\nFROM users\nWHERE name = 'alice'\n  AND password_hash = crypt('s3cretP@ss', password_hash);\n-- Returns row if password matches\n\n-- Cost factor comparison:\nSELECT gen_salt('bf', 8);   -- fast (~40ms)\nSELECT gen_salt('bf', 12);  -- slower (~600ms)\nSELECT gen_salt('bf', 14);  -- very slow (~2.5s)\n\n-- DO NOT use MD5 or SHA for passwords:\n-- SELECT md5('password'); -- too fast, no salt\n-- SELECT digest('password', 'sha256'); -- also bad", tags: ['advanced', 'pgcrypto', 'bcrypt', 'password-hashing'] },
  { id: 'pg-advanced-l3-008', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you perform symmetric encryption with pgcrypto?', options: ['Use the encrypt() function with a key', 'Use AES_ENCRYPT() like in MySQL', 'Use pgp_sym_encrypt(data, key) and pgp_sym_decrypt(encrypted, key) — these functions use the OpenPGP standard with AES-128 by default, providing authenticated encryption with compression, suitable for encrypting sensitive column data', 'Use SSL/TLS for encryption at rest'], correctAnswer: 3, explanation: 'pgp_sym_encrypt/decrypt use the OpenPGP symmetric encryption standard. The data is encrypted with a passphrase using AES (default) or other ciphers. The encrypted output includes metadata, random session key, and optional compression. Each encryption produces different ciphertext (due to random session key), preventing pattern analysis. For raw encryption without PGP overhead, use encrypt()/decrypt() with raw cipher modes.', codeSnippet: "-- Encrypt sensitive data:\nINSERT INTO patient_records (name, ssn_encrypted)\nVALUES (\n  'John Doe',\n  pgp_sym_encrypt('123-45-6789', 'encryption-key-here')\n);\n\n-- Decrypt data:\nSELECT name,\n  pgp_sym_decrypt(ssn_encrypted, 'encryption-key-here') AS ssn\nFROM patient_records;\n\n-- With compression and cipher options:\nSELECT pgp_sym_encrypt(\n  'sensitive data',\n  'my-key',\n  'compress-algo=1, cipher-algo=aes256'\n);\n\n-- Wrong key returns error:\nSELECT pgp_sym_decrypt(encrypted_col, 'wrong-key');\n-- ERROR: Wrong key or corrupt data\n\n-- Raw encryption (without PGP wrapper):\nSELECT encrypt('data', 'key', 'aes');", tags: ['advanced', 'pgcrypto', 'symmetric-encryption', 'pgp'] },
  { id: 'pg-advanced-l3-009', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you use public-key encryption with pgcrypto?', options: ['PostgreSQL does not support asymmetric encryption', 'Use RSA functions directly', 'Use pgp_pub_encrypt(data, public_key) to encrypt and pgp_pub_decrypt(encrypted, private_key) to decrypt — this allows encrypting data with a public key so that only the holder of the corresponding private key can decrypt it', 'Import OpenSSL libraries manually'], correctAnswer: 0, explanation: 'PGP public-key encryption in pgcrypto uses RSA (or ElGamal/DSA) keys. Data encrypted with the public key can only be decrypted with the corresponding private key. This is useful when data must be encrypted by applications that should not have decryption capability. The private key can be password-protected. Key management (generation, rotation, storage) must be handled outside PostgreSQL.', codeSnippet: "-- Generate keys outside PostgreSQL:\n-- gpg --gen-key\n-- gpg --export -a 'User' > public.key\n-- gpg --export-secret-keys -a 'User' > private.key\n\n-- Read key into variable:\n\\set pubkey `cat public.key`\n\n-- Encrypt with public key:\nINSERT INTO secrets (data)\nVALUES (\n  pgp_pub_encrypt(\n    'top secret message',\n    dearmor(:'pubkey')\n  )\n);\n\n-- Decrypt with private key:\nSELECT pgp_pub_decrypt(\n  data,\n  dearmor(:'privkey'),\n  'key-password'  -- if key is password-protected\n) FROM secrets;\n\n-- Encrypt with sub-keys for key rotation:\n-- Allows re-encryption without decrypting", tags: ['advanced', 'pgcrypto', 'public-key', 'pgp-encryption'] },
  { id: 'pg-advanced-l3-010', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'What are event triggers in PostgreSQL?', options: ['Event triggers fire on DML operations like INSERT/UPDATE', 'Event triggers are scheduled timer events', 'Event triggers fire on DDL (Data Definition Language) events like CREATE, ALTER, DROP — they capture database-wide schema changes, allowing you to log, restrict, or react to structural modifications across all objects in the database', 'Event triggers are the same as regular triggers'], correctAnswer: 1, explanation: 'Event triggers are database-level triggers that fire on DDL commands (unlike regular triggers which fire on DML). They capture events like ddl_command_start, ddl_command_end, table_rewrite, and sql_drop. Event triggers can log all schema changes for auditing, prevent certain DDL operations, or automatically perform actions after schema changes. They fire for all objects in the database, not just specific tables.', codeSnippet: "-- Create event trigger function:\nCREATE FUNCTION log_ddl()\nRETURNS event_trigger AS $$\nDECLARE\n  obj RECORD;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    INSERT INTO ddl_log(event, command_tag, object_type,\n      schema_name, object_identity, ts)\n    VALUES (TG_EVENT, obj.command_tag, obj.object_type,\n      obj.schema_name, obj.object_identity, now());\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Create event trigger:\nCREATE EVENT TRIGGER log_all_ddl\n  ON ddl_command_end\n  EXECUTE FUNCTION log_ddl();\n\n-- Now any DDL is logged:\nCREATE TABLE test (id INT);\n-- Logged: CREATE TABLE public.test", tags: ['advanced', 'event-triggers', 'ddl-logging', 'schema-auditing'] },
  { id: 'pg-advanced-l3-011', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'What are the different event trigger events in PostgreSQL?', options: ['INSERT, UPDATE, DELETE, TRUNCATE', 'CONNECT, DISCONNECT, ERROR', 'ddl_command_start fires before DDL execution, ddl_command_end fires after successful DDL, sql_drop fires when objects are dropped (providing dropped object details), and table_rewrite fires when a table is rewritten (e.g., ALTER TABLE changing column type)', 'BEFORE, AFTER, INSTEAD OF'], correctAnswer: 2, explanation: 'The four event trigger events serve different purposes: ddl_command_start is for preventing DDL (raise exception to block), ddl_command_end is for logging/reacting after DDL succeeds, sql_drop provides details about dropped objects (via pg_event_trigger_dropped_objects()), and table_rewrite fires when ALTER TABLE requires rewriting the table data. Each event provides different context functions.', codeSnippet: "-- Prevent dropping tables in production:\nCREATE FUNCTION prevent_drop()\nRETURNS event_trigger AS $$\nDECLARE\n  obj RECORD;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()\n  LOOP\n    IF obj.object_type = 'table'\n       AND obj.schema_name = 'public' THEN\n      RAISE EXCEPTION\n        'Cannot drop table %.% in production!',\n        obj.schema_name, obj.object_name;\n    END IF;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER no_drop_tables\n  ON sql_drop\n  EXECUTE FUNCTION prevent_drop();\n\n-- Block DDL during maintenance windows:\nCREATE EVENT TRIGGER block_ddl\n  ON ddl_command_start\n  WHEN TAG IN ('DROP TABLE', 'DROP SCHEMA')\n  EXECUTE FUNCTION prevent_drop();", tags: ['advanced', 'event-triggers', 'ddl-events', 'sql-drop'] },
  { id: 'pg-advanced-l3-012', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you filter event triggers to specific DDL commands?', options: ['Use a WHERE clause in the CREATE EVENT TRIGGER', 'Use IF statements inside the function only', 'Use the WHEN TAG IN clause in CREATE EVENT TRIGGER — this filters the trigger to fire only for specific DDL command tags like CREATE TABLE, ALTER TABLE, DROP INDEX, etc., reducing unnecessary trigger invocations', 'Event triggers always fire for all DDL commands'], correctAnswer: 3, explanation: 'The WHEN TAG IN filter restricts which DDL commands activate the trigger. Command tags are strings like CREATE TABLE, ALTER TABLE, DROP INDEX, CREATE FUNCTION, etc. This is more efficient than filtering inside the function because the trigger is not even invoked for non-matching commands. Multiple tags can be listed. Without WHEN, the trigger fires for all DDL commands of the specified event type.', codeSnippet: "-- Only trigger on table-related DDL:\nCREATE EVENT TRIGGER track_table_changes\n  ON ddl_command_end\n  WHEN TAG IN (\n    'CREATE TABLE',\n    'ALTER TABLE',\n    'DROP TABLE',\n    'CREATE TABLE AS'\n  )\n  EXECUTE FUNCTION log_ddl();\n\n-- Only trigger on index changes:\nCREATE EVENT TRIGGER track_index_changes\n  ON ddl_command_end\n  WHEN TAG IN (\n    'CREATE INDEX',\n    'DROP INDEX',\n    'REINDEX'\n  )\n  EXECUTE FUNCTION log_ddl();\n\n-- Block specific operations:\nCREATE EVENT TRIGGER no_drop_functions\n  ON ddl_command_start\n  WHEN TAG IN ('DROP FUNCTION', 'DROP PROCEDURE')\n  EXECUTE FUNCTION block_operation();", tags: ['advanced', 'event-triggers', 'when-tag-in', 'command-filtering'] },
  { id: 'pg-advanced-l3-013', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'What are advisory locks in PostgreSQL?', options: ['Locks that advise the user about performance issues', 'Locks automatically placed by the query optimizer', 'Application-defined locks using pg_advisory_lock(key) — they are cooperative locks that do not protect any database object but allow applications to coordinate access to shared resources using arbitrary integer keys, managed entirely by application logic', 'Locks that warn before data modification'], correctAnswer: 0, explanation: 'Advisory locks are a PostgreSQL feature for application-level locking. Unlike row or table locks that are automatically acquired and released by SQL operations, advisory locks are explicitly managed by the application. They use 64-bit integer keys (or pairs of 32-bit integers) as lock identifiers. Applications must agree on the meaning of each key. Advisory locks are very fast because they bypass the regular lock manager overhead.', codeSnippet: "-- Session-level advisory lock (held until release or disconnect):\nSELECT pg_advisory_lock(12345);\n-- ... do exclusive work ...\nSELECT pg_advisory_unlock(12345);\n\n-- Transaction-level lock (released at end of transaction):\nSELECT pg_advisory_xact_lock(12345);\n-- Released automatically at COMMIT/ROLLBACK\n\n-- Non-blocking try-lock:\nSELECT pg_try_advisory_lock(12345);\n-- Returns true if acquired, false if already locked\n\n-- Shared advisory lock (multiple readers):\nSELECT pg_advisory_lock_shared(12345);\n\n-- Two-key form:\nSELECT pg_advisory_lock(1, 100);\n-- Key space: (classid, objid)", tags: ['advanced', 'advisory-locks', 'pg-advisory-lock', 'application-locking'] },
  { id: 'pg-advanced-l3-014', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'How do you use advisory locks to prevent duplicate job processing?', options: ['Use a unique constraint on job ID', 'Use row-level locks with SELECT FOR UPDATE', 'Use pg_try_advisory_lock(job_id) to attempt acquiring a lock — if it returns true, the job is not being processed by another worker, if false, another worker already has the lock and the job should be skipped', 'Use a separate lock table with INSERT'], correctAnswer: 1, explanation: 'Advisory locks are ideal for job queue deduplication because they are fast, do not create table bloat, and automatically release on disconnect. Using pg_try_advisory_lock (non-blocking) allows workers to skip already-locked jobs. The transaction-level variant (pg_try_advisory_xact_lock) automatically releases when the transaction ends, providing clean semantics for job processing.', codeSnippet: "-- Worker picks up and processes jobs:\nCREATE FUNCTION process_next_job()\nRETURNS TEXT AS $$\nDECLARE\n  job RECORD;\nBEGIN\n  FOR job IN\n    SELECT * FROM job_queue\n    WHERE status = 'pending'\n    ORDER BY created_at\n  LOOP\n    -- Try to lock this job:\n    IF pg_try_advisory_xact_lock(job.id) THEN\n      -- Got the lock, process it:\n      UPDATE job_queue SET status = 'processing'\n      WHERE id = job.id;\n\n      -- ... do work ...\n\n      UPDATE job_queue SET status = 'done'\n      WHERE id = job.id;\n      RETURN 'Processed job ' || job.id;\n    END IF;\n    -- Lock failed, another worker has it\n  END LOOP;\n  RETURN 'No available jobs';\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'advisory-locks', 'job-queue', 'deduplication'] },
  { id: 'pg-advanced-l3-015', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'What is the difference between session-level and transaction-level advisory locks?', options: ['Session locks are faster than transaction locks', 'They are identical in behavior', 'Transaction locks cannot be shared', 'Session-level locks (pg_advisory_lock) persist until explicitly released or the session disconnects, while transaction-level locks (pg_advisory_xact_lock) are automatically released when the transaction commits or rolls back — transaction-level is safer as it prevents forgotten locks'], correctAnswer: 2, explanation: 'Session-level advisory locks require explicit pg_advisory_unlock() calls and persist across transaction boundaries. Forgetting to unlock creates resource leaks. Transaction-level locks are automatically released at COMMIT/ROLLBACK, making them safer. However, session-level locks are necessary when you need a lock that spans multiple transactions. Always prefer transaction-level locks unless you specifically need cross-transaction locking.', codeSnippet: "-- Session-level: must manually release\nSELECT pg_advisory_lock(100);\nBEGIN;\n  -- work...\nCOMMIT;  -- lock still held!\nSELECT pg_advisory_unlock(100); -- now released\n\n-- WARNING: locks are re-entrant!\nSELECT pg_advisory_lock(100);  -- count = 1\nSELECT pg_advisory_lock(100);  -- count = 2\nSELECT pg_advisory_unlock(100); -- count = 1\nSELECT pg_advisory_unlock(100); -- count = 0 (released)\n\n-- Transaction-level: auto-released\nBEGIN;\n  SELECT pg_advisory_xact_lock(200);\n  -- work...\nCOMMIT; -- lock automatically released\n\n-- Check active advisory locks:\nSELECT * FROM pg_locks WHERE locktype = 'advisory';", tags: ['advanced', 'advisory-locks', 'session-vs-transaction', 'lock-lifecycle'] },
  { id: 'pg-advanced-l3-016', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a custom aggregate function in PostgreSQL?', options: ['Use CREATE FUNCTION with GROUP BY', 'Use CREATE AGGREGATE with a state transition function (sfunc), state type (stype), and optional final function (ffunc) — the sfunc is called for each input row accumulating state, and the optional ffunc transforms the final state into the output value', 'Custom aggregates require C extensions', 'Override the built-in SUM function'], correctAnswer: 3, explanation: 'Custom aggregates extend PostgreSQL beyond built-in aggregates (SUM, AVG, etc.). They require at minimum a state transition function and state type. The sfunc receives the current state and the new input value, returning the updated state. The optional ffunc converts the final state to the output format. Optional components include an initial state value, combinefunc for parallel aggregation, and serialfunc/deserialfunc for distributed execution.', codeSnippet: "-- Custom aggregate: geometric mean\nCREATE FUNCTION geomean_sfunc(\n  state NUMERIC[], val NUMERIC\n) RETURNS NUMERIC[] AS $$\nBEGIN\n  IF val > 0 THEN\n    RETURN ARRAY[\n      state[1] + ln(val),  -- sum of logs\n      state[2] + 1          -- count\n    ];\n  END IF;\n  RETURN state;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE FUNCTION geomean_ffunc(state NUMERIC[])\nRETURNS NUMERIC AS $$\nBEGIN\n  IF state[2] = 0 THEN RETURN NULL; END IF;\n  RETURN exp(state[1] / state[2]);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE geometric_mean(NUMERIC) (\n  sfunc = geomean_sfunc,\n  stype = NUMERIC[],\n  finalfunc = geomean_ffunc,\n  initcond = '{0,0}'\n);\n\nSELECT geometric_mean(price) FROM products;", tags: ['advanced', 'custom-aggregates', 'create-aggregate', 'sfunc'] },
  { id: 'pg-advanced-l3-017', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'What is the combinefunc in a custom aggregate and when is it needed?', options: ['combinefunc combines multiple tables', 'combinefunc merges aggregate results from multiple queries', 'combinefunc merges two partial aggregate states produced by parallel workers — it is required for the aggregate to participate in parallel query execution, where each worker computes a partial state and the leader combines them', 'combinefunc is called between each sfunc call'], correctAnswer: 0, explanation: 'When PostgreSQL executes an aggregate in parallel, each worker processes a subset of rows and produces a partial state. The combinefunc takes two partial states and merges them into one. Without a combinefunc, the aggregate is marked PARALLEL UNSAFE and cannot benefit from parallel execution. The combinefunc must be associative and commutative. For simple aggregates like SUM, combining two partial sums is trivial.', codeSnippet: "-- Parallel-safe custom aggregate:\nCREATE FUNCTION sum_combine(\n  state1 NUMERIC, state2 NUMERIC\n) RETURNS NUMERIC AS $$\n  SELECT COALESCE(state1, 0) + COALESCE(state2, 0);\n$$ LANGUAGE sql;\n\nCREATE AGGREGATE my_sum(NUMERIC) (\n  sfunc = numeric_add,\n  stype = NUMERIC,\n  combinefunc = sum_combine,  -- enables parallel\n  initcond = '0',\n  parallel = safe\n);\n\n-- For the geometric mean:\nCREATE FUNCTION geomean_combine(\n  state1 NUMERIC[], state2 NUMERIC[]\n) RETURNS NUMERIC[] AS $$\nBEGIN\n  RETURN ARRAY[\n    state1[1] + state2[1],  -- combine log sums\n    state1[2] + state2[2]   -- combine counts\n  ];\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Add combinefunc to existing aggregate:\n-- Must recreate the aggregate", tags: ['advanced', 'custom-aggregates', 'combinefunc', 'parallel-aggregation'] },
  { id: 'pg-advanced-l3-018', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Table Inheritance', question: 'What is table inheritance in PostgreSQL?', options: ['Table inheritance is the same as foreign keys', 'Table inheritance means tables inherit indexes from other tables', 'A child table created with INHERITS (parent) inherits all columns, constraints, and default values from the parent — queries on the parent automatically include rows from all children, providing a form of polymorphic data access', 'Table inheritance copies data between tables'], correctAnswer: 1, explanation: 'Table inheritance allows creating hierarchies of tables where children share the parent structure. Querying the parent returns all rows from parent and children (use ONLY to query just the parent). Children can add extra columns. This was the original partitioning mechanism before declarative partitioning in PG 10. It is still useful for modeling IS-A relationships. Note that UNIQUE constraints and foreign keys do not span the hierarchy.', codeSnippet: "-- Parent table:\nCREATE TABLE vehicles (\n  id SERIAL PRIMARY KEY,\n  make TEXT NOT NULL,\n  model TEXT NOT NULL,\n  year INTEGER\n);\n\n-- Child tables inherit all columns:\nCREATE TABLE cars (\n  num_doors INTEGER,\n  trunk_size NUMERIC\n) INHERITS (vehicles);\n\nCREATE TABLE trucks (\n  payload_capacity NUMERIC,\n  num_axles INTEGER\n) INHERITS (vehicles);\n\n-- Insert into children:\nINSERT INTO cars (make, model, year, num_doors)\nVALUES ('Toyota', 'Camry', 2024, 4);\n\n-- Query parent gets ALL vehicles:\nSELECT * FROM vehicles;  -- includes cars & trucks\n\n-- Query ONLY parent:\nSELECT * FROM ONLY vehicles;  -- excludes children", tags: ['advanced', 'table-inheritance', 'inherits', 'polymorphic'] },
  { id: 'pg-advanced-l3-019', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Table Inheritance', question: 'What are the limitations of table inheritance in PostgreSQL?', options: ['Table inheritance has no limitations', 'Only two levels of inheritance are allowed', 'UNIQUE constraints, primary keys, and foreign key references do not span the inheritance hierarchy — a unique constraint on the parent does not prevent duplicates across parent and children, and foreign keys cannot reference the parent to include child rows', 'Inherited tables cannot be indexed'], correctAnswer: 2, explanation: 'The key limitations are: UNIQUE and PRIMARY KEY constraints are per-table (duplicates can exist across parent and children), foreign keys referencing the parent do not see child rows, CHECK and NOT NULL constraints are inherited but can be overridden, indexes are not inherited (each table needs its own), and triggers on the parent do not fire for child table operations. Declarative partitioning (PARTITION OF) addresses some of these limitations.', codeSnippet: "-- UNIQUE does NOT span hierarchy:\nCREATE TABLE parent (id INT UNIQUE);\nCREATE TABLE child () INHERITS (parent);\n\nINSERT INTO parent VALUES (1);  -- OK\nINSERT INTO child VALUES (1);   -- Also OK! Duplicate!\n\n-- Foreign keys don't see children:\nCREATE TABLE orders (\n  vehicle_id INT REFERENCES vehicles(id)  -- parent only!\n);\nINSERT INTO cars (id, make, model) VALUES (100, 'BMW', 'X5');\nINSERT INTO orders (vehicle_id) VALUES (100);\n-- ERROR: violates foreign key (car row not visible)\n\n-- Triggers not inherited:\nCREATE TRIGGER trg ON vehicles ...;  -- parent only\n-- Must create separate triggers on each child\n\n-- Check inheritance:\nSELECT tableoid::regclass, * FROM vehicles;", tags: ['advanced', 'table-inheritance', 'limitations', 'unique-constraints'] },
  { id: 'pg-advanced-l3-020', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'RULE System', question: 'What is the PostgreSQL RULE system?', options: ['Rules enforce data validation like constraints', 'Rules are execution plans cached by the planner', 'The RULE system rewrites queries at parse time — CREATE RULE defines query rewrite rules that transform one SQL statement into another before execution, historically used for updatable views and now largely superseded by INSTEAD OF triggers', 'Rules manage database connection routing'], correctAnswer: 3, explanation: 'Rules operate at the query rewrite stage of query processing. When a query matches a rule, it is rewritten according to the rule definition. The most common use was making views updatable before INSTEAD OF triggers existed. Rules have subtle semantic differences from triggers: they operate on the query level (rewriting the whole query) rather than row level. For most use cases, triggers are now preferred over rules.', codeSnippet: "-- Simple view with rules (old approach):\nCREATE VIEW active_users AS\nSELECT * FROM users WHERE active = TRUE;\n\n-- Rule to make view insertable:\nCREATE RULE insert_active_user AS\n  ON INSERT TO active_users\n  DO INSTEAD\n  INSERT INTO users (name, email, active)\n  VALUES (NEW.name, NEW.email, TRUE);\n\n-- Rule to redirect deletes:\nCREATE RULE soft_delete AS\n  ON DELETE TO users\n  DO INSTEAD\n  UPDATE users SET active = FALSE, deleted_at = now()\n  WHERE id = OLD.id;\n\n-- DO NOTHING rule (suppress operation):\nCREATE RULE no_delete_admins AS\n  ON DELETE TO users\n  WHERE OLD.role = 'admin'\n  DO INSTEAD NOTHING;", tags: ['advanced', 'rule-system', 'query-rewrite', 'create-rule'] },
  { id: 'pg-advanced-l3-021', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'RULE System', question: 'What are the key differences between rules and triggers?', options: ['Rules are faster than triggers in all cases', 'They behave identically for all operations', 'Rules operate at the query rewriting stage before execution (transforming the SQL statement itself), while triggers operate at execution time on individual rows — rules can silently suppress or redirect operations, triggers provide row-level access to NEW/OLD', 'Triggers can only run AFTER operations, rules only BEFORE'], correctAnswer: 0, explanation: 'Rules rewrite queries at parse time — the original query may be replaced entirely. Triggers fire during query execution on each affected row. Key differences: rules operate on the whole query (not per-row), rules can add INSTEAD actions, rules interact poorly with RETURNING clauses, rules cannot see the actual data being modified during rewrite. INSTEAD OF triggers (PG 9.1+) replaced the main use case for rules on views.', codeSnippet: "-- Rule: rewrites the query (before execution)\nCREATE RULE redirect AS ON INSERT TO view_a\n  DO INSTEAD INSERT INTO table_b VALUES (NEW.*);\n-- INSERT INTO view_a VALUES (1);\n-- Actually executes: INSERT INTO table_b VALUES (1);\n\n-- Trigger: fires during execution (per row)\nCREATE TRIGGER trg INSTEAD OF INSERT ON view_a\n  FOR EACH ROW EXECUTE FUNCTION redirect_func();\n-- INSERT INTO view_a VALUES (1);\n-- Calls redirect_func() for each row\n\n-- Rules break with COPY:\nCOPY view_a FROM 'file.csv';  -- rule may not work\n-- Triggers work correctly with COPY\n\n-- Rules break with RETURNING:\nINSERT INTO view_a VALUES (1) RETURNING *;\n-- Rule may return wrong results\n-- Triggers handle RETURNING correctly\n\n-- Recommendation: prefer triggers over rules", tags: ['advanced', 'rule-system', 'rules-vs-triggers', 'query-rewrite'] },
  { id: 'pg-advanced-l3-022', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you find all points within a given radius using PostGIS?', options: ['Use a BETWEEN clause on coordinates', 'Use mathematical formulas in a WHERE clause', 'Use ST_DWithin(geometry_a, geometry_b, distance) which returns true if two geometries are within the specified distance — it uses the spatial index efficiently and for geography type the distance is in meters', 'Use a subquery with manual Haversine calculation'], correctAnswer: 1, explanation: 'ST_DWithin is the preferred function for proximity searches because it can use spatial indexes effectively. Unlike ST_Distance() < threshold (which computes distance for every row), ST_DWithin uses the index to first filter by bounding box, then checks the exact distance. For geography type, the distance parameter is in meters. Combine with ORDER BY <-> for nearest-neighbor sorting.', codeSnippet: "-- Find restaurants within 1km:\nSELECT name, address,\n  ST_Distance(\n    location::geography,\n    ST_SetSRID(ST_MakePoint(-73.985, 40.748), 4326)::geography\n  ) AS distance_m\nFROM restaurants\nWHERE ST_DWithin(\n  location::geography,\n  ST_SetSRID(ST_MakePoint(-73.985, 40.748), 4326)::geography,\n  1000  -- 1000 meters = 1km\n)\nORDER BY distance_m;\n\n-- With geometry (projected CRS, meters):\nSELECT name\nFROM restaurants\nWHERE ST_DWithin(\n  ST_Transform(location, 32618),  -- UTM Zone 18N\n  ST_Transform(my_point, 32618),\n  1000  -- meters in projected CRS\n);", tags: ['advanced', 'postgis', 'st-dwithin', 'proximity-search'] },
  { id: 'pg-advanced-l3-023', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you calculate the area of a polygon in PostGIS?', options: ['Count the points in the polygon', 'Use LENGTH() on the polygon', 'Use ST_Area(geometry) — for geometry type it returns the area in SRID units squared, for geography type it returns the area in square meters, making geography type preferred for accurate real-world area calculations', 'Multiply width by height of the bounding box'], correctAnswer: 2, explanation: 'ST_Area computes the area of polygonal geometries. With geometry type, the result is in the square of whatever unit the SRID uses (degrees squared for SRID 4326, which is meaningless). With geography type, the result is in square meters using geodesic calculations. For geometry, transform to a projected CRS first for meaningful results. ST_Area supports POLYGON, MULTIPOLYGON, and geometry collections.', codeSnippet: "-- Area in square meters (geography):\nSELECT name,\n  ST_Area(boundary::geography) AS area_m2,\n  ST_Area(boundary::geography) / 1e6 AS area_km2\nFROM districts;\n\n-- Area with projected CRS (geometry):\nSELECT name,\n  ST_Area(ST_Transform(boundary, 32632)) AS area_m2\nFROM districts;\n\n-- Create a polygon and measure:\nSELECT ST_Area(\n  ST_GeomFromText(\n    'POLYGON((0 0, 1 0, 1 1, 0 1, 0 0))',\n    32632  -- UTM zone 32N\n  )\n); -- 1.0 square meter\n\n-- Percentage of total area:\nSELECT name,\n  ST_Area(boundary::geography) /\n  SUM(ST_Area(boundary::geography)) OVER () * 100\n  AS pct\nFROM districts;", tags: ['advanced', 'postgis', 'st-area', 'area-calculation'] },
  { id: 'pg-advanced-l3-024', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you generate secure random tokens with pgcrypto?', options: ['Use random() function', 'Use md5(now()::text)', 'Use gen_random_bytes(n) to generate n cryptographically secure random bytes — encode them as hex or base64 for use as API tokens, session IDs, or password reset tokens that are unpredictable and resistant to guessing attacks', 'Use uuid_generate_v1() for tokens'], correctAnswer: 3, explanation: 'gen_random_bytes() uses the operating system cryptographic random number generator (e.g., /dev/urandom on Linux), producing unpredictable output suitable for security-sensitive purposes. Unlike random() (which is a PRNG and predictable) or md5(now()) (which depends on clock), gen_random_bytes provides cryptographic-strength randomness. Encode the output as hex (32 chars for 16 bytes) or base64 for use as string tokens.', codeSnippet: "-- Generate a 32-byte (256-bit) secure token:\nSELECT encode(gen_random_bytes(32), 'hex') AS token;\n-- e.g.: a1b2c3d4e5f6...64 hex chars\n\n-- Base64 token:\nSELECT encode(gen_random_bytes(24), 'base64') AS token;\n-- e.g.: xYz123AbC...32 base64 chars\n\n-- Use in table:\nCREATE TABLE api_tokens (\n  id SERIAL PRIMARY KEY,\n  user_id INT REFERENCES users(id),\n  token TEXT DEFAULT encode(gen_random_bytes(32), 'hex'),\n  created_at TIMESTAMPTZ DEFAULT now(),\n  expires_at TIMESTAMPTZ DEFAULT now() + INTERVAL '30 days'\n);\n\n-- DO NOT use these for tokens:\n-- random(): predictable PRNG\n-- md5(now()::text): time-based, guessable\n-- uuid_generate_v1(): contains MAC address + time", tags: ['advanced', 'pgcrypto', 'random-tokens', 'gen-random-bytes'] },
  { id: 'pg-advanced-l3-025', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'How do you use advisory locks for rate limiting?', options: ['Advisory locks cannot be used for rate limiting', 'Use pg_sleep for rate limiting instead', 'Use pg_try_advisory_lock with a key derived from the resource and time window — if the lock is already held, the rate limit has been reached, providing a lightweight distributed rate limiter without additional infrastructure', 'Use a counter table with row locks'], correctAnswer: 0, explanation: 'Advisory locks can implement simple rate limiting by using keys that combine a resource identifier with a time bucket. For example, hash(user_id, minute_number) creates a unique lock per user per minute. pg_try_advisory_lock returns false if the lock is already held, indicating the rate limit is exceeded. This is extremely lightweight compared to counter-based approaches and does not create any table bloat.', codeSnippet: "-- Rate limit: one API call per user per minute\nCREATE FUNCTION check_rate_limit(\n  user_id INT,\n  resource TEXT,\n  window_seconds INT DEFAULT 60\n) RETURNS BOOLEAN AS $$\nDECLARE\n  lock_key BIGINT;\n  time_bucket BIGINT;\nBEGIN\n  -- Time bucket: current epoch / window\n  time_bucket := extract(epoch from now())::BIGINT\n    / window_seconds;\n\n  -- Unique key from user + resource + time\n  lock_key := hashtext(\n    user_id || ':' || resource || ':' || time_bucket\n  );\n\n  -- Try to acquire lock:\n  RETURN pg_try_advisory_xact_lock(lock_key);\n  -- true = allowed, false = rate limited\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Usage:\nSELECT check_rate_limit(42, 'api_endpoint');\n-- First call: true (allowed)\n-- Second call within 60s: false (limited)", tags: ['advanced', 'advisory-locks', 'rate-limiting', 'distributed-lock'] },
  { id: 'pg-advanced-l3-026', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create an ordered-set aggregate in PostgreSQL?', options: ['Use ORDER BY inside a regular aggregate', 'Use CREATE AGGREGATE with WITHIN GROUP syntax', 'Define a CREATE AGGREGATE with hypothetical set functions using the HYPOTHETICAL keyword, or use ORDER BY in the aggregate definition with the SORTOP clause — ordered-set aggregates process data in a specific order defined by the WITHIN GROUP clause at call time', 'Ordered-set aggregates are not user-definable'], correctAnswer: 1, explanation: 'Ordered-set aggregates are a special kind of aggregate where the input ordering matters. Built-in examples include percentile_cont, percentile_disc, mode, and rank/dense_rank as hypothetical-set functions. User-defined ordered-set aggregates can be created but are complex, requiring careful handling of sorted input. The WITHIN GROUP (ORDER BY ...) clause at call time specifies the sort order.', codeSnippet: "-- Built-in ordered-set aggregates:\nSELECT\n  percentile_cont(0.5)\n    WITHIN GROUP (ORDER BY salary) AS median,\n  percentile_cont(ARRAY[0.25, 0.5, 0.75])\n    WITHIN GROUP (ORDER BY salary) AS quartiles,\n  mode()\n    WITHIN GROUP (ORDER BY department) AS most_common_dept\nFROM employees;\n\n-- Hypothetical-set aggregate:\nSELECT\n  rank(50000)\n    WITHIN GROUP (ORDER BY salary) AS rank_of_50k,\n  percent_rank(50000)\n    WITHIN GROUP (ORDER BY salary) AS pct_rank\nFROM employees;\n\n-- Custom: concatenate in order\nCREATE AGGREGATE sorted_concat(TEXT ORDER BY sort_key INT) (\n  sfunc = ...,\n  stype = TEXT\n);", tags: ['advanced', 'custom-aggregates', 'ordered-set', 'within-group'] },
  { id: 'pg-advanced-l3-027', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you perform spatial joins in PostGIS?', options: ['Use regular JOIN with coordinate columns', 'Use CROSS JOIN with distance calculations', 'Use JOIN with spatial predicates like ST_Intersects, ST_Contains, ST_Within — these spatial joins use GiST indexes for efficient matching, allowing you to combine datasets based on geographic relationships rather than key equality', 'Spatial joins are not possible in SQL'], correctAnswer: 2, explanation: 'Spatial joins combine rows from two tables based on geographic relationships rather than attribute equality. Common spatial predicates for joins include ST_Intersects (geometries overlap), ST_Contains/ST_Within (containment), ST_DWithin (proximity), and ST_Crosses (line crosses polygon). The GiST spatial index is critical for performance — without it, PostgreSQL must compare every geometry pair (O(n*m)).', codeSnippet: "-- Find which district each point belongs to:\nSELECT p.name AS poi_name,\n       d.name AS district_name\nFROM points_of_interest p\nJOIN districts d\n  ON ST_Within(p.location, d.boundary);\n\n-- Count buildings per zone:\nSELECT z.name, COUNT(b.id) AS building_count\nFROM zones z\nLEFT JOIN buildings b\n  ON ST_Intersects(b.footprint, z.area)\nGROUP BY z.name;\n\n-- Find roads that cross a river:\nSELECT r.name AS road, w.name AS river\nFROM roads r\nJOIN waterways w\n  ON ST_Crosses(r.geom, w.geom);\n\n-- Nearest neighbor join:\nSELECT DISTINCT ON (s.id)\n  s.name AS school,\n  h.name AS nearest_hospital,\n  ST_Distance(s.geom, h.geom) AS dist\nFROM schools s\nCROSS JOIN LATERAL (\n  SELECT name, geom FROM hospitals\n  ORDER BY geom <-> s.geom LIMIT 1\n) h;", tags: ['advanced', 'postgis', 'spatial-join', 'st-intersects'] },
  { id: 'pg-advanced-l3-028', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you use event triggers to enforce naming conventions?', options: ['Use CHECK constraints on table names', 'Use a CI/CD pipeline for validation', 'Create a ddl_command_end event trigger that inspects newly created objects and raises an exception if they do not follow the naming convention — using pg_event_trigger_ddl_commands() to get the object details for validation', 'Naming conventions cannot be enforced in the database'], correctAnswer: 3, explanation: 'Event triggers on ddl_command_end can validate naming conventions for all database objects. The pg_event_trigger_ddl_commands() function provides details about the created or altered objects, including their names. You can check for patterns like lowercase-only names, required prefixes/suffixes, maximum length, or prohibited characters. This enforces consistency at the database level, regardless of which tool or developer makes changes.', codeSnippet: "CREATE FUNCTION enforce_naming()\nRETURNS event_trigger AS $$\nDECLARE\n  obj RECORD;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    -- Tables must be lowercase with underscores:\n    IF obj.object_type = 'table'\n       AND obj.object_identity !~ '^[a-z][a-z0-9_]*\\.[a-z][a-z0-9_]*$'\n    THEN\n      RAISE EXCEPTION\n        'Table name must be lowercase with underscores: %',\n        obj.object_identity;\n    END IF;\n\n    -- Indexes must start with idx_:\n    IF obj.object_type = 'index'\n       AND obj.object_identity !~ '\\.idx_'\n    THEN\n      RAISE EXCEPTION\n        'Index must start with idx_: %',\n        obj.object_identity;\n    END IF;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER enforce_naming_convention\n  ON ddl_command_end\n  EXECUTE FUNCTION enforce_naming();", tags: ['advanced', 'event-triggers', 'naming-conventions', 'governance'] },
  { id: 'pg-advanced-l3-029', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you implement column-level encryption with pgcrypto?', options: ['Enable TDE (Transparent Data Encryption)', 'Use SSL for column encryption', 'Encrypt specific column values using pgp_sym_encrypt() on write and pgp_sym_decrypt() on read — storing the encrypted data as bytea type, with the encryption key managed securely outside the database or in a restricted table', 'Use ALTER COLUMN SET ENCRYPTED'], correctAnswer: 0, explanation: 'Column-level encryption encrypts individual column values while keeping other columns in plaintext. This provides defense-in-depth: even if the database is compromised, encrypted columns remain protected without the key. The key must be managed carefully — avoid storing it in the same database. Consider using a key management service (KMS). Encrypted columns cannot be indexed or searched (except with blind index techniques).', codeSnippet: "-- Table with encrypted columns:\nCREATE TABLE patients (\n  id SERIAL PRIMARY KEY,\n  name TEXT,  -- not encrypted\n  ssn BYTEA,  -- encrypted\n  diagnosis BYTEA  -- encrypted\n);\n\n-- Insert with encryption:\nINSERT INTO patients (name, ssn, diagnosis)\nVALUES (\n  'John Doe',\n  pgp_sym_encrypt('123-45-6789', current_setting('app.encryption_key')),\n  pgp_sym_encrypt('Diagnosis text', current_setting('app.encryption_key'))\n);\n\n-- Read with decryption:\nSELECT name,\n  pgp_sym_decrypt(ssn, current_setting('app.encryption_key')) AS ssn,\n  pgp_sym_decrypt(diagnosis, current_setting('app.encryption_key'))\nFROM patients;\n\n-- Set key for session:\nSET app.encryption_key = 'your-secret-key-here';", tags: ['advanced', 'pgcrypto', 'column-encryption', 'data-protection'] },
  { id: 'pg-advanced-l3-030', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'How do you implement a distributed mutex using advisory locks?', options: ['Use pg_advisory_lock with a consistent hash of the resource name as the lock key — all PostgreSQL sessions using the same hash function will compete for the same lock, providing mutual exclusion across all connected clients', 'Advisory locks only work within a single session', 'Use table-level locks instead', 'Use a file-based lock mechanism'], correctAnswer: 1, explanation: 'Advisory locks provide database-level mutual exclusion. By using a consistent hashing scheme (e.g., hashtext() on a resource name), all sessions can coordinate without prior agreement on integer keys. pg_advisory_lock blocks until the lock is available, while pg_try_advisory_lock returns immediately. This pattern is used for singleton services, schema migrations, and any operation that must run exclusively.', codeSnippet: "-- Distributed mutex using resource name:\nCREATE FUNCTION acquire_mutex(resource TEXT)\nRETURNS BOOLEAN AS $$\nBEGIN\n  RETURN pg_try_advisory_lock(hashtext(resource));\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE FUNCTION release_mutex(resource TEXT)\nRETURNS BOOLEAN AS $$\nBEGIN\n  RETURN pg_advisory_unlock(hashtext(resource));\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Usage: only one process runs migration\nDO $$\nBEGIN\n  IF pg_try_advisory_lock(hashtext('run_migration')) THEN\n    -- We got the lock, run migration:\n    RAISE NOTICE 'Running migration...';\n    -- ... migration logic ...\n    PERFORM pg_advisory_unlock(hashtext('run_migration'));\n  ELSE\n    RAISE NOTICE 'Migration already running elsewhere';\n  END IF;\nEND;\n$$;", tags: ['advanced', 'advisory-locks', 'distributed-mutex', 'hashtext'] },
  { id: 'pg-advanced-l3-031', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a moving average aggregate?', options: ['Use the built-in moving_avg() function', 'Use window functions instead of custom aggregates', 'Define a custom aggregate with an array state that maintains a sliding window of recent values — the sfunc appends new values and trims the array to the window size, and the ffunc computes the average of the window contents', 'Moving averages require a procedural loop'], correctAnswer: 2, explanation: 'While window functions (AVG OVER ROWS BETWEEN) are the standard approach for moving averages in queries, a custom aggregate can encapsulate the moving average logic for reuse. The state stores an array of recent values. Each sfunc call adds the new value and removes the oldest if the window is full. The ffunc computes the average. However, for most cases, window functions are simpler and more efficient.', codeSnippet: "-- Custom moving average aggregate:\nCREATE FUNCTION ma_sfunc(\n  state NUMERIC[], val NUMERIC, window_size INT\n) RETURNS NUMERIC[] AS $$\nBEGIN\n  state := array_append(state, val);\n  IF array_length(state, 1) > window_size THEN\n    state := state[2:];\n  END IF;\n  RETURN state;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE FUNCTION ma_ffunc(state NUMERIC[])\nRETURNS NUMERIC AS $$\nBEGIN\n  RETURN (\n    SELECT AVG(v) FROM unnest(state) v\n  );\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE moving_avg(NUMERIC, INT) (\n  sfunc = ma_sfunc,\n  stype = NUMERIC[],\n  finalfunc = ma_ffunc,\n  initcond = '{}'\n);\n\n-- Simpler: use window function\nSELECT date, value,\n  AVG(value) OVER (ORDER BY date ROWS 6 PRECEDING)\nFROM daily_data;", tags: ['advanced', 'custom-aggregates', 'moving-average', 'window-state'] },
  { id: 'pg-advanced-l3-032', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you create a buffer zone around a geometry in PostGIS?', options: ['Add a padding value to coordinates', 'Use ST_Expand on the geometry', 'Use ST_Buffer(geometry, distance) to create a polygon that represents all points within the specified distance from the input geometry — for points it creates a circle, for lines a corridor, and for polygons an expanded boundary', 'Use ST_Envelope to create a buffer'], correctAnswer: 3, explanation: 'ST_Buffer is a fundamental spatial analysis function. It creates a new polygon by expanding or shrinking a geometry by a specified distance. Positive distance expands outward, negative distance shrinks inward (for polygons). Buffer style can be customized (round vs flat end caps, mitre vs round joins). For geography type, cast to geometry with a projected CRS for accurate results, as ST_Buffer works in CRS units.', codeSnippet: "-- Buffer around a point (circle):\nSELECT ST_Buffer(\n  ST_MakePoint(0, 0)::geometry,\n  100  -- 100 units radius\n);\n\n-- Buffer around a line (corridor):\nSELECT ST_Buffer(\n  ST_GeomFromText('LINESTRING(0 0, 100 100)'),\n  10  -- 10 units wide on each side\n);\n\n-- Real-world: 500m buffer around a school\nSELECT name,\n  ST_Buffer(\n    ST_Transform(location, 32632),  -- project to meters\n    500  -- 500 meter buffer\n  ) AS buffer_zone\nFROM schools;\n\n-- Find buildings within 500m of a road:\nSELECT b.name\nFROM buildings b, roads r\nWHERE r.name = 'Main Street'\n  AND ST_Intersects(\n    b.location,\n    ST_Buffer(r.geom, 500)\n  );", tags: ['advanced', 'postgis', 'st-buffer', 'buffer-zone'] },
  { id: 'pg-advanced-l3-033', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Table Inheritance', question: 'How does table inheritance compare to declarative partitioning?', options: ['They are identical features', 'Inheritance is newer and better than partitioning', 'Declarative partitioning (PARTITION BY) is preferred for data distribution — it supports automatic partition pruning, global indexes (PG 11+), and partition-wise joins, while inheritance is better for polymorphic data models where each child has different extra columns', 'Partitioning is for read-only data, inheritance for writable data'], correctAnswer: 0, explanation: 'Declarative partitioning (introduced in PG 10) is optimized for distributing large datasets by a partition key. It provides automatic tuple routing, partition pruning, and better optimizer support. Table inheritance is a more general mechanism for IS-A relationships where children can have different columns. For pure data distribution, always use declarative partitioning. For polymorphic schemas (e.g., different event types with different attributes), inheritance may be appropriate.', codeSnippet: "-- Declarative partitioning (preferred for distribution):\nCREATE TABLE events (\n  id BIGSERIAL,\n  event_date DATE,\n  data JSONB\n) PARTITION BY RANGE (event_date);\n\nCREATE TABLE events_2024_q1\n  PARTITION OF events\n  FOR VALUES FROM ('2024-01-01') TO ('2024-04-01');\n\n-- Automatic partition pruning:\nSELECT * FROM events\nWHERE event_date = '2024-02-15';\n-- Only scans events_2024_q1\n\n-- Table inheritance (for polymorphic models):\nCREATE TABLE events_base (\n  id SERIAL, ts TIMESTAMPTZ, user_id INT\n);\nCREATE TABLE click_events (\n  url TEXT, element TEXT\n) INHERITS (events_base);\nCREATE TABLE purchase_events (\n  product_id INT, amount NUMERIC\n) INHERITS (events_base);", tags: ['advanced', 'table-inheritance', 'partitioning', 'comparison'] },
  { id: 'pg-advanced-l3-034', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you use event triggers to track schema changes over time?', options: ['Enable the pg_stat_statements extension', 'Use pg_dump for change tracking', 'Create a ddl_command_end event trigger that records every DDL operation into a schema_changelog table — capturing the command tag, object details, user, timestamp, and optionally the full DDL command text from current_query()', 'Parse the PostgreSQL WAL logs'], correctAnswer: 1, explanation: 'A schema changelog implemented via event triggers provides a complete audit trail of all DDL changes. The pg_event_trigger_ddl_commands() function in ddl_command_end provides structured details about what was created or altered. Adding current_query() captures the exact SQL. This enables tracking who changed what and when, supporting compliance requirements and troubleshooting schema issues.', codeSnippet: "CREATE TABLE schema_changelog (\n  id SERIAL PRIMARY KEY,\n  event TEXT,\n  command_tag TEXT,\n  object_type TEXT,\n  schema_name TEXT,\n  object_identity TEXT,\n  ddl_command TEXT,\n  executed_by TEXT DEFAULT current_user,\n  executed_at TIMESTAMPTZ DEFAULT now()\n);\n\nCREATE FUNCTION track_ddl()\nRETURNS event_trigger AS $$\nDECLARE\n  obj RECORD;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    INSERT INTO schema_changelog(\n      event, command_tag, object_type,\n      schema_name, object_identity, ddl_command)\n    VALUES (\n      TG_EVENT, obj.command_tag, obj.object_type,\n      obj.schema_name, obj.object_identity,\n      current_query()\n    );\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER track_schema_changes\n  ON ddl_command_end\n  EXECUTE FUNCTION track_ddl();", tags: ['advanced', 'event-triggers', 'schema-changelog', 'ddl-tracking'] },
  { id: 'pg-advanced-l3-035', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'What is ST_Intersects and how does it differ from ST_Overlaps?', options: ['They are identical functions', 'ST_Intersects is for points, ST_Overlaps is for polygons', 'ST_Intersects returns true if two geometries share any portion of space (including touching boundaries), while ST_Overlaps is stricter — it requires that the geometries overlap in a region of the same dimension and neither fully contains the other', 'ST_Overlaps is the negation of ST_Intersects'], correctAnswer: 2, explanation: 'ST_Intersects is the most inclusive spatial predicate — it returns true if geometries share any space at all (interior or boundary). ST_Overlaps is more specific: the overlap must be the same dimension as the inputs, and neither geometry can fully contain the other. For example, two partially overlapping polygons: ST_Intersects = true, ST_Overlaps = true. A point on a polygon boundary: ST_Intersects = true, ST_Overlaps = false (different dimensions).', codeSnippet: "-- ST_Intersects: any shared space\nSELECT ST_Intersects(\n  ST_GeomFromText('POLYGON((0 0,2 0,2 2,0 2,0 0))'),\n  ST_GeomFromText('POLYGON((1 1,3 1,3 3,1 3,1 1))')\n); -- true (they overlap)\n\nSELECT ST_Intersects(\n  ST_GeomFromText('POINT(2 2)'),\n  ST_GeomFromText('POLYGON((0 0,2 0,2 2,0 2,0 0))')\n); -- true (point on boundary)\n\n-- ST_Overlaps: same-dimension partial overlap\nSELECT ST_Overlaps(\n  ST_GeomFromText('POLYGON((0 0,2 0,2 2,0 2,0 0))'),\n  ST_GeomFromText('POLYGON((1 1,3 1,3 3,1 3,1 1))')\n); -- true (partial polygon overlap)\n\nSELECT ST_Overlaps(\n  ST_GeomFromText('POLYGON((0 0,2 0,2 2,0 2,0 0))'),\n  ST_GeomFromText('POLYGON((0 0,1 0,1 1,0 1,0 0))')\n); -- false (second is contained)", tags: ['advanced', 'postgis', 'st-intersects', 'st-overlaps'] },
  { id: 'pg-advanced-l3-036', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you implement HMAC (Hash-based Message Authentication Code) with pgcrypto?', options: ['Use digest() with a salt parameter', 'Use crypt() with a secret key', 'Use hmac(data, key, algorithm) which computes a keyed hash — HMAC ensures both data integrity and authentication, verifying that the message was not tampered with and was created by someone who knows the secret key', 'HMAC requires an external library'], correctAnswer: 3, explanation: 'HMAC combines a hash function with a secret key to produce an authentication code. Unlike a plain hash (which anyone can compute), HMAC requires the secret key, so it proves the message came from a trusted source. pgcrypto hmac() supports md5, sha1, sha224, sha256, sha384, and sha512. HMAC is commonly used for API request signing, webhook verification, and tamper detection.', codeSnippet: "-- Compute HMAC-SHA256:\nSELECT encode(\n  hmac('message data', 'secret-key', 'sha256'),\n  'hex'\n) AS hmac_hex;\n\n-- Webhook signature verification:\nCREATE FUNCTION verify_webhook(\n  payload TEXT,\n  signature TEXT,\n  secret TEXT\n) RETURNS BOOLEAN AS $$\nBEGIN\n  RETURN encode(\n    hmac(payload, secret, 'sha256'), 'hex'\n  ) = signature;\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\n-- Signed URLs:\nCREATE FUNCTION sign_url(url TEXT, secret TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  RETURN url || '&sig=' || encode(\n    hmac(url, secret, 'sha256'), 'hex'\n  );\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;", tags: ['advanced', 'pgcrypto', 'hmac', 'authentication'] },
  { id: 'pg-advanced-l3-037', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a custom aggregate that works as a window function?', options: ['Custom aggregates cannot be used as window functions', 'Use CREATE WINDOW FUNCTION instead', 'Any custom aggregate automatically works as a window function — it can be used with OVER (PARTITION BY ... ORDER BY ...) clauses, and optionally you can define a moving aggregate mode with mstype, msfunc, and minvfunc for efficient sliding window calculations', 'Only built-in aggregates support OVER clauses'], correctAnswer: 0, explanation: 'All aggregate functions in PostgreSQL (including custom ones) can be used as window functions by adding an OVER clause. For basic usage, the aggregate computes over the window frame by re-running from scratch for each row. For efficient sliding windows, define moving aggregate support: msfunc (forward step), minvfunc (inverse step to remove rows leaving the window), and mstype (moving state type). The inverse function avoids recomputation.', codeSnippet: "-- Custom aggregate with moving support:\nCREATE FUNCTION sum_sfunc(state NUMERIC, val NUMERIC)\nRETURNS NUMERIC AS $$\n  SELECT COALESCE(state, 0) + COALESCE(val, 0);\n$$ LANGUAGE sql;\n\nCREATE FUNCTION sum_invfunc(state NUMERIC, val NUMERIC)\nRETURNS NUMERIC AS $$\n  SELECT state - COALESCE(val, 0);\n$$ LANGUAGE sql;\n\nCREATE AGGREGATE my_sum(NUMERIC) (\n  sfunc = sum_sfunc,\n  stype = NUMERIC,\n  initcond = '0',\n  -- Moving aggregate support:\n  msfunc = sum_sfunc,\n  mstype = NUMERIC,\n  minvfunc = sum_invfunc,\n  minitcond = '0'\n);\n\n-- Use as window function:\nSELECT date, amount,\n  my_sum(amount) OVER (\n    ORDER BY date\n    ROWS BETWEEN 6 PRECEDING AND CURRENT ROW\n  ) AS rolling_sum\nFROM daily_sales;", tags: ['advanced', 'custom-aggregates', 'window-function', 'moving-aggregate'] },
  { id: 'pg-advanced-l3-038', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'How do you view currently held advisory locks?', options: ['Use SHOW LOCKS command', 'Use pg_advisory_lock_status() function', 'Query the pg_locks system view filtering by locktype = advisory — this shows the PID, lock key (classid/objid), lock mode (exclusive/share), and whether the lock is granted, helping diagnose lock contention and forgotten locks', 'Advisory locks are invisible to monitoring tools'], correctAnswer: 1, explanation: 'pg_locks contains information about all locks in the system, including advisory locks. For advisory locks, classid and objid together form the lock key (for 64-bit keys, classid contains the upper 32 bits and objid the lower 32 bits). The granted column shows if the lock is held (true) or waiting (false). Join with pg_stat_activity to find which sessions hold which locks.', codeSnippet: "-- View all advisory locks:\nSELECT\n  l.pid,\n  l.classid,\n  l.objid,\n  l.mode,\n  l.granted,\n  a.usename,\n  a.application_name,\n  a.query\nFROM pg_locks l\nJOIN pg_stat_activity a ON a.pid = l.pid\nWHERE l.locktype = 'advisory';\n\n-- 64-bit key reconstruction:\nSELECT\n  (classid::BIGINT << 32) | objid::BIGINT AS lock_key,\n  mode, granted, pid\nFROM pg_locks\nWHERE locktype = 'advisory';\n\n-- Find blocked sessions waiting for advisory locks:\nSELECT pid, usename, query, wait_event\nFROM pg_stat_activity\nWHERE wait_event_type = 'Lock'\n  AND pid IN (\n    SELECT pid FROM pg_locks\n    WHERE locktype = 'advisory' AND NOT granted\n  );", tags: ['advanced', 'advisory-locks', 'pg-locks', 'monitoring'] },
  { id: 'pg-advanced-l3-039', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you convert between coordinate reference systems (CRS) in PostGIS?', options: ['Coordinates are automatically converted', 'Use CAST to change CRS', 'Use ST_Transform(geometry, target_srid) to reproject geometries between coordinate systems — converting from geographic coordinates (SRID 4326, degrees) to projected coordinates (like UTM, meters) for accurate distance and area calculations', 'CRS conversion requires external tools'], correctAnswer: 2, explanation: 'ST_Transform reprojects geometries from one CRS to another using the PROJ library. Common transformations include: SRID 4326 (WGS84 geographic, degrees) to a local UTM zone (meters) for accurate measurements, or between national coordinate systems. The spatial_ref_sys table contains all available CRS definitions. Transformation is computationally expensive, so create function-based indexes on transformed geometries if queried frequently.', codeSnippet: "-- Transform from WGS84 to UTM Zone 32N:\nSELECT ST_Transform(\n  ST_SetSRID(ST_MakePoint(13.4050, 52.5200), 4326),\n  32632  -- UTM Zone 32N (meters)\n);\n\n-- Accurate distance in meters:\nSELECT ST_Distance(\n  ST_Transform(a.geom, 32632),\n  ST_Transform(b.geom, 32632)\n) AS distance_meters\nFROM places a, places b\nWHERE a.name = 'Berlin' AND b.name = 'Munich';\n\n-- Find the right UTM zone for a point:\nSELECT\n  FLOOR((ST_X(geom) + 180) / 6) + 1 AS utm_zone\nFROM places;\n\n-- Functional index for transformed geometry:\nCREATE INDEX idx_places_utm\n  ON places USING gist (\n    ST_Transform(location, 32632)\n  );", tags: ['advanced', 'postgis', 'st-transform', 'coordinate-systems'] },
  { id: 'pg-advanced-l3-040', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'RULE System', question: 'How do you use rules to implement an updatable view with complex logic?', options: ['Rules cannot make views updatable', 'Use INSTEAD OF triggers exclusively', 'Create DO INSTEAD rules for INSERT, UPDATE, and DELETE on the view — each rule defines how the corresponding DML operation should be translated to modifications on the underlying base tables', 'Mark the view as WITH CHECK OPTION'], correctAnswer: 3, explanation: 'While INSTEAD OF triggers are now preferred, rules still work for updatable views. You define separate rules for each DML operation. DO INSTEAD replaces the original operation. DO ALSO adds operations in addition to the original. Rules can reference NEW (for INSERT/UPDATE) and OLD (for UPDATE/DELETE). The main advantage of rules over triggers is that they operate at the query level, which can be more efficient for bulk operations.', codeSnippet: "CREATE VIEW employee_directory AS\nSELECT e.id, e.name, e.email, d.name AS dept_name\nFROM employees e\nJOIN departments d ON e.dept_id = d.id;\n\nCREATE RULE emp_dir_insert AS\n  ON INSERT TO employee_directory\n  DO INSTEAD\n  INSERT INTO employees (name, email, dept_id)\n  VALUES (\n    NEW.name,\n    NEW.email,\n    (SELECT id FROM departments WHERE name = NEW.dept_name)\n  );\n\nCREATE RULE emp_dir_update AS\n  ON UPDATE TO employee_directory\n  DO INSTEAD\n  UPDATE employees\n  SET name = NEW.name, email = NEW.email\n  WHERE id = OLD.id;\n\nCREATE RULE emp_dir_delete AS\n  ON DELETE TO employee_directory\n  DO INSTEAD\n  DELETE FROM employees WHERE id = OLD.id;\n\n-- Now the view is updatable:\nINSERT INTO employee_directory(name, email, dept_name)\nVALUES ('Alice', 'alice@co.com', 'Engineering');", tags: ['advanced', 'rule-system', 'updatable-view', 'do-instead'] },
  { id: 'pg-advanced-l3-041', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you perform geocoding and reverse geocoding with PostGIS?', options: ['PostGIS includes built-in geocoding for all countries', 'Use Google Maps API calls from SQL', 'Use the PostGIS Tiger Geocoder extension (for US addresses) or combine PostGIS with external geocoding services — PostGIS provides the spatial functions for the lookup (ST_DWithin, ST_Distance with KNN) but address data must be loaded separately', 'Geocoding requires a separate GIS application'], correctAnswer: 0, explanation: 'PostGIS itself does not include address databases, but it provides all the spatial operations needed for geocoding. The Tiger Geocoder extension provides US Census TIGER data integration for address geocoding. For global geocoding, you can import OpenStreetMap data into PostGIS using tools like osm2pgsql, then use spatial queries for geocoding. Reverse geocoding uses ST_DWithin and KNN (<->) ordering to find the nearest address to a coordinate.', codeSnippet: "-- Reverse geocoding: find nearest address to a point\nSELECT address, city,\n  ST_Distance(\n    location::geography,\n    ST_SetSRID(ST_MakePoint(-73.985, 40.748), 4326)::geography\n  ) AS distance_m\nFROM addresses\nORDER BY location <->\n  ST_SetSRID(ST_MakePoint(-73.985, 40.748), 4326)\nLIMIT 1;\n\n-- US Tiger Geocoder:\nCREATE EXTENSION postgis_tiger_geocoder;\n\n-- Geocode an address:\nSELECT rating, ST_AsText(geomout),\n  pprint_addy(addy)\nFROM geocode('100 Main St, New York, NY');\n\n-- Reverse geocode:\nSELECT pprint_addy(addy)\nFROM reverse_geocode(\n  ST_SetSRID(ST_MakePoint(-73.985, 40.748), 4326)\n);", tags: ['advanced', 'postgis', 'geocoding', 'reverse-geocoding'] },
  { id: 'pg-advanced-l3-042', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'What are the security considerations when using pgcrypto for encryption?', options: ['pgcrypto is perfectly secure with no considerations needed', 'Only use pgcrypto with SSL connections', 'Encryption keys appear in plaintext in SQL queries, pg_stat_activity, and query logs — keys should be passed via session variables (SET/current_setting), the server should use SSL, statement logging should be carefully configured, and keys should be rotated regularly', 'pgcrypto is not secure enough for production use'], correctAnswer: 1, explanation: 'pgcrypto security concerns: 1) Keys in SQL strings appear in pg_stat_activity, pg_stat_statements, and query logs (use current_setting() with custom GUCs). 2) Decrypted data exists in server memory. 3) The database superuser can always access data. 4) No key management built in (use external KMS). 5) Encrypted columns cannot be indexed for search. 6) Connection must use SSL to protect keys in transit. 7) Consider TDE for disk-level protection.', codeSnippet: "-- BAD: key visible in query log\nSELECT pgp_sym_encrypt(data, 'my-secret-key')\nFROM sensitive;\n\n-- BETTER: pass key via session variable\nSET app.enc_key = 'my-secret-key';\n-- (set from application, not in SQL file)\n\nSELECT pgp_sym_encrypt(\n  data, current_setting('app.enc_key')\n) FROM sensitive;\n\n-- Prevent key leaking in logs:\n-- postgresql.conf:\n-- log_min_duration_statement = -1\n-- Or use: ALTER SYSTEM SET log_statement = 'ddl';\n\n-- Verify SSL is active:\nSELECT ssl, version FROM pg_stat_ssl\nWHERE pid = pg_backend_pid();\n\n-- Key rotation pattern:\nUPDATE secrets SET\n  encrypted = pgp_sym_encrypt(\n    pgp_sym_decrypt(encrypted, old_key),\n    new_key\n  );", tags: ['advanced', 'pgcrypto', 'security-considerations', 'key-management'] },
  { id: 'pg-advanced-l3-043', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you use the table_rewrite event trigger?', options: ['table_rewrite fires when data is rewritten by VACUUM', 'table_rewrite fires during logical replication', 'table_rewrite fires when ALTER TABLE causes a complete table rewrite — such as changing a column type, adding a column with a volatile default, or adding a NOT NULL constraint with a default, allowing you to block or log these potentially expensive operations', 'table_rewrite fires when a table is truncated'], correctAnswer: 2, explanation: 'Certain ALTER TABLE operations require PostgreSQL to rewrite the entire table (creating a new copy with the modifications). This can be extremely expensive for large tables and locks the table exclusively for the duration. The table_rewrite event trigger fires before the rewrite begins, allowing you to prevent it (by raising an exception) during peak hours or log a warning. Use pg_event_trigger_table_rewrite_oid() to get the affected table.', codeSnippet: "CREATE FUNCTION warn_table_rewrite()\nRETURNS event_trigger AS $$\nDECLARE\n  table_oid OID;\n  table_name TEXT;\n  table_size TEXT;\nBEGIN\n  table_oid := pg_event_trigger_table_rewrite_oid();\n  SELECT relname INTO table_name\n  FROM pg_class WHERE oid = table_oid;\n  table_size := pg_size_pretty(\n    pg_total_relation_size(table_oid));\n\n  -- Block during business hours:\n  IF extract(hour from now()) BETWEEN 9 AND 17 THEN\n    RAISE EXCEPTION\n      'Table rewrite of % (%) blocked during business hours',\n      table_name, table_size;\n  END IF;\n\n  RAISE WARNING 'Table rewrite: % (%)', table_name, table_size;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER warn_rewrite\n  ON table_rewrite\n  EXECUTE FUNCTION warn_table_rewrite();", tags: ['advanced', 'event-triggers', 'table-rewrite', 'alter-table'] },
  { id: 'pg-advanced-l3-044', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'How do you use advisory locks with two-key form for namespaced locking?', options: ['Two-key advisory locks use a string and integer pair', 'Two-key locks require a custom extension', 'pg_advisory_lock(classid, objid) uses two 32-bit integers — this allows organizing locks into namespaces where classid represents the resource type (e.g., table OID) and objid represents the specific resource (e.g., row ID)', 'Two-key form is just syntactic sugar for single-key'], correctAnswer: 3, explanation: 'The two-key form pg_advisory_lock(INT, INT) uses two 32-bit integers instead of one 64-bit integer. This naturally supports namespaced locking: use the first integer as a class/type identifier and the second as the specific resource ID. A common pattern uses the table OID as classid and the row primary key as objid, creating per-row advisory locks without the overhead of SELECT FOR UPDATE.', codeSnippet: "-- Namespaced locking pattern:\n-- Class 1 = user operations\n-- Class 2 = order operations\n-- Class 3 = report generation\n\n-- Lock user 42 for exclusive processing:\nSELECT pg_advisory_xact_lock(1, 42);\n\n-- Lock order 100 for exclusive processing:\nSELECT pg_advisory_xact_lock(2, 100);\n\n-- Using table OID as namespace:\nSELECT pg_advisory_xact_lock(\n  'users'::regclass::INT,  -- table OID as classid\n  42  -- row ID as objid\n);\n\n-- Non-blocking with namespace:\nIF pg_try_advisory_xact_lock(\n  'orders'::regclass::INT, order_id\n) THEN\n  -- process order\nEND IF;\n\n-- View namespaced locks:\nSELECT classid, objid, mode, granted\nFROM pg_locks WHERE locktype = 'advisory';", tags: ['advanced', 'advisory-locks', 'two-key', 'namespaced-locking'] },
  { id: 'pg-advanced-l3-045', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a string aggregation function with custom separator and ordering?', options: ['Use built-in string_agg() which already supports ordering', 'String aggregation requires application code', 'While string_agg(value, separator ORDER BY ...) is built-in, you can create a custom aggregate for more complex logic — such as adding prefixes, filtering during aggregation, or applying transformations to each value before concatenation', 'Custom string aggregates are not possible'], correctAnswer: 0, explanation: 'PostgreSQL built-in string_agg() already handles most string aggregation needs with ORDER BY support. However, custom aggregates can extend this with transformation logic, conditional inclusion, or complex formatting. The aggregate state accumulates values, and the final function joins them. For simple cases, string_agg() with ORDER BY and FILTER clauses is sufficient and more efficient.', codeSnippet: "-- Built-in string_agg with ordering:\nSELECT department,\n  string_agg(name, ', ' ORDER BY name) AS members\nFROM employees\nGROUP BY department;\n\n-- With FILTER:\nSELECT\n  string_agg(name, ', ') FILTER (WHERE active) AS active_list,\n  string_agg(name, ', ') FILTER (WHERE NOT active) AS inactive_list\nFROM employees;\n\n-- Custom aggregate: numbered list\nCREATE FUNCTION numbered_list_sfunc(\n  state TEXT[], val TEXT\n) RETURNS TEXT[] AS $$\nBEGIN\n  RETURN array_append(state, val);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE FUNCTION numbered_list_ffunc(state TEXT[])\nRETURNS TEXT AS $$\nDECLARE\n  result TEXT := '';\nBEGIN\n  FOR i IN 1..array_length(state, 1) LOOP\n    result := result || i || '. ' || state[i] || E'\\n';\n  END LOOP;\n  RETURN result;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'custom-aggregates', 'string-agg', 'ordering'] },
  { id: 'pg-advanced-l3-046', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you work with LineString geometries for route analysis in PostGIS?', options: ['Use arrays of points instead of LineStrings', 'Use ST_MakeLine to create routes and ST_Length for distance — LineString functions include ST_StartPoint, ST_EndPoint, ST_NPoints for endpoints and vertex count, ST_LineSubstring for extracting portions, and ST_LineLocatePoint for finding positions along a line', 'Routes require a graph database', 'Use the pgRouting extension exclusively'], correctAnswer: 1, explanation: 'PostGIS provides comprehensive LineString manipulation functions. ST_MakeLine creates lines from points. ST_Length measures total length. ST_LineSubstring extracts a portion (0.0 to 1.0 fraction). ST_LineLocatePoint finds where a point projects onto a line. ST_LineInterpolatePoint finds the point at a given fraction along the line. For routing on road networks, the pgRouting extension adds graph algorithms (Dijkstra, A*, etc.).', codeSnippet: "-- Create a LineString:\nSELECT ST_MakeLine(ARRAY[\n  ST_MakePoint(0, 0),\n  ST_MakePoint(1, 1),\n  ST_MakePoint(2, 0)\n]);\n\n-- Route length in meters:\nSELECT ST_Length(\n  ST_Transform(route_geom, 32632)\n) AS length_meters\nFROM routes;\n\n-- Point at 50% along the line:\nSELECT ST_LineInterpolatePoint(route_geom, 0.5)\nAS midpoint FROM routes;\n\n-- Extract first half of route:\nSELECT ST_LineSubstring(route_geom, 0.0, 0.5)\nAS first_half FROM routes;\n\n-- Where on the line is nearest to a point?\nSELECT ST_LineLocatePoint(\n  route_geom,\n  ST_MakePoint(1.5, 0.5)\n) AS fraction_along -- 0.0 to 1.0\nFROM routes;", tags: ['advanced', 'postgis', 'linestring', 'route-analysis'] },
  { id: 'pg-advanced-l3-047', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Table Inheritance', question: 'How do you query only the parent table excluding child rows in an inheritance hierarchy?', options: ['Use WHERE tableoid = parent_oid', 'Use SELECT ... FROM table WHERE NOT inherited', 'Use SELECT ... FROM ONLY parent_table — the ONLY keyword restricts the query to the specified table alone, excluding all rows from inherited child tables, useful when you need data stored directly in the parent', 'Use SELECT ... FROM parent_table LIMIT to parent rows'], correctAnswer: 2, explanation: 'By default, queries on a parent table include all rows from child tables. The ONLY keyword overrides this behavior, querying just the parent. This applies to SELECT, UPDATE, and DELETE. You can also use the tableoid system column to identify which table each row comes from (parent or which child). This is useful for targeted maintenance operations or when child tables should be queried separately.', codeSnippet: "-- Query ALL vehicles (parent + children):\nSELECT * FROM vehicles;\n-- Returns rows from vehicles, cars, and trucks\n\n-- Query ONLY the parent:\nSELECT * FROM ONLY vehicles;\n-- Returns only direct vehicle rows\n\n-- Identify source table per row:\nSELECT tableoid::regclass AS source_table, *\nFROM vehicles;\n-- source_table | id | make  | model\n-- vehicles     | 1  | ...   | ...\n-- cars         | 2  | ...   | ...\n-- trucks       | 3  | ...   | ...\n\n-- ONLY with UPDATE (affect parent only):\nUPDATE ONLY vehicles SET year = 2024\nWHERE year IS NULL;\n\n-- ONLY with DELETE:\nDELETE FROM ONLY vehicles WHERE id = 1;\n\n-- List inheritance hierarchy:\nSELECT c.relname AS child\nFROM pg_inherits i\nJOIN pg_class c ON c.oid = i.inhrelid\nWHERE i.inhparent = 'vehicles'::regclass;", tags: ['advanced', 'table-inheritance', 'only-keyword', 'parent-query'] },
  { id: 'pg-advanced-l3-048', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'RULE System', question: 'What are the dangers and pitfalls of using PostgreSQL rules?', options: ['Rules are completely safe with no pitfalls', 'Rules are deprecated and removed from PostgreSQL', 'Rules can cause unexpected behavior: they may fire multiple times with COPY, interact poorly with RETURNING, make it hard to reason about execution order, can create infinite loops with DO ALSO, and bypass row-level security — triggers are almost always the safer choice', 'The only pitfall is that rules are slower than triggers'], correctAnswer: 3, explanation: 'Rules have several well-known pitfalls: 1) COPY bypasses rules on the target table. 2) RETURNING clauses may return unexpected results. 3) DO ALSO rules can create infinite loops if the additional action matches the rule again. 4) Rules are invisible in EXPLAIN plans, making debugging difficult. 5) Multiple rules interact in complex ways. 6) Rules bypass RLS policies. The PostgreSQL community generally recommends triggers over rules for new code.', codeSnippet: "-- Pitfall 1: COPY bypasses rules\nCREATE RULE no_delete AS ON DELETE TO users\n  DO INSTEAD NOTHING;\nDELETE FROM users; -- rule works, nothing deleted\nCOPY (SELECT * FROM users) TO '/dev/null';\n-- COPY ignores rules!\n\n-- Pitfall 2: Infinite loop risk\nCREATE RULE log_insert AS ON INSERT TO orders\n  DO ALSO\n  INSERT INTO orders_log\n  SELECT NEW.*;\n-- If orders_log inherits from orders... infinite loop!\n\n-- Pitfall 3: RETURNING confusion\nCREATE RULE redirect AS ON INSERT TO view_a\n  DO INSTEAD INSERT INTO table_b VALUES (NEW.*);\nINSERT INTO view_a VALUES (1) RETURNING *;\n-- May return nothing or wrong data!\n\n-- Recommendation: use triggers instead\nCREATE TRIGGER trg INSTEAD OF INSERT ON view_a\n  FOR EACH ROW EXECUTE FUNCTION handle_insert();", tags: ['advanced', 'rule-system', 'pitfalls', 'dangers'] },
  { id: 'pg-advanced-l3-049', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you implement a blind index for searching encrypted data?', options: ['Decrypt all data for each search query', 'Use B-tree indexes on encrypted columns', 'Create a separate column storing HMAC or truncated hash of the plaintext — the blind index allows equality searches on encrypted data without decryption, by computing the same HMAC on the search term and comparing against the stored blind index', 'Encrypted data cannot be searched at all'], correctAnswer: 0, explanation: 'A blind index stores a deterministic, irreversible transformation (HMAC) of the plaintext alongside the encrypted value. To search, compute the same HMAC on the search term and match against the blind index column. The HMAC uses a separate key from the encryption key. This enables equality lookups without decrypting all rows. The tradeoff is that identical plaintexts produce identical blind indexes, which leaks equality information.', codeSnippet: "-- Table with encryption and blind index:\nCREATE TABLE patients (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  ssn_encrypted BYTEA,\n  ssn_blind_index BYTEA  -- for searching\n);\n\nCREATE INDEX idx_ssn_blind ON patients(ssn_blind_index);\n\n-- Insert with both encrypted and blind index:\nINSERT INTO patients (name, ssn_encrypted, ssn_blind_index)\nVALUES (\n  'John',\n  pgp_sym_encrypt('123-45-6789', current_setting('app.enc_key')),\n  hmac('123-45-6789', current_setting('app.blind_key'), 'sha256')\n);\n\n-- Search by SSN without decrypting all rows:\nSELECT name,\n  pgp_sym_decrypt(ssn_encrypted, current_setting('app.enc_key'))\nFROM patients\nWHERE ssn_blind_index = hmac(\n  '123-45-6789',\n  current_setting('app.blind_key'),\n  'sha256'\n);", tags: ['advanced', 'pgcrypto', 'blind-index', 'searchable-encryption'] },
  { id: 'pg-advanced-l3-050', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you compute the centroid of a polygon in PostGIS?', options: ['Average all vertex coordinates manually', 'Use ST_Center() function', 'Use ST_Centroid(geometry) which returns the geometric center of mass of a geometry — for simple convex polygons the centroid is inside the polygon, but for concave or multipart geometries the centroid may fall outside the geometry, in which case ST_PointOnSurface is more appropriate', 'Centroids can only be computed for circles'], correctAnswer: 1, explanation: 'ST_Centroid computes the mathematical center of mass. For points, it returns the point itself. For lines, it returns the midpoint by length. For polygons, it returns the area centroid. The centroid of a concave polygon (like a crescent) may be outside the polygon. ST_PointOnSurface guarantees a point that lies within the geometry, which is better for labeling. Both are commonly used for visualization and spatial analysis.', codeSnippet: "-- Centroid of a polygon:\nSELECT ST_AsText(\n  ST_Centroid(\n    ST_GeomFromText('POLYGON((0 0, 4 0, 4 3, 0 3, 0 0))')\n  )\n); -- POINT(2 1.5)\n\n-- Centroid may be outside concave polygon:\nSELECT ST_Within(\n  ST_Centroid(geom), geom\n) AS centroid_inside\nFROM concave_shapes;\n-- May be false!\n\n-- ST_PointOnSurface always inside:\nSELECT ST_Within(\n  ST_PointOnSurface(geom), geom\n) AS always_inside\nFROM any_shapes;\n-- Always true!\n\n-- Label placement for districts:\nSELECT name,\n  ST_AsText(ST_PointOnSurface(boundary)) AS label_point\nFROM districts;", tags: ['advanced', 'postgis', 'st-centroid', 'point-on-surface'] },
  { id: 'pg-advanced-l3-051', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you create an event trigger that adds comments to newly created objects?', options: ['Use ALTER DEFAULT PRIVILEGES for comments', 'Use a naming convention parser', 'Create a ddl_command_end event trigger that automatically adds COMMENT ON statements for newly created tables, views, or functions — using pg_event_trigger_ddl_commands() to identify the objects and EXECUTE format() to run dynamic COMMENT statements', 'PostgreSQL does not support comments on objects'], correctAnswer: 2, explanation: 'Event triggers can enforce documentation standards by automatically adding placeholder comments or validating that comments exist on newly created objects. The ddl_command_end event provides the object identity and type through pg_event_trigger_ddl_commands(). You can either add template comments automatically or raise a warning/exception if the creator did not include a COMMENT statement.', codeSnippet: "CREATE FUNCTION auto_comment()\nRETURNS event_trigger AS $$\nDECLARE\n  obj RECORD;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    IF obj.command_tag = 'CREATE TABLE' THEN\n      EXECUTE format(\n        'COMMENT ON TABLE %s IS $c$TODO: Add description for %s$c$',\n        obj.object_identity, obj.object_identity\n      );\n    ELSIF obj.command_tag = 'CREATE FUNCTION' THEN\n      EXECUTE format(\n        'COMMENT ON FUNCTION %s IS $c$TODO: Document this function$c$',\n        obj.object_identity\n      );\n    END IF;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER auto_doc\n  ON ddl_command_end\n  WHEN TAG IN ('CREATE TABLE', 'CREATE FUNCTION')\n  EXECUTE FUNCTION auto_comment();", tags: ['advanced', 'event-triggers', 'auto-documentation', 'comments'] },
  { id: 'pg-advanced-l3-052', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a percentile aggregate without using built-in percentile_cont?', options: ['Custom percentile aggregates are impossible', 'Use approximate percentiles only', 'Create a custom aggregate that accumulates all values in an array (sfunc), sorts the array in the final function (ffunc), and returns the value at the requested percentile position — demonstrating how ordered-set aggregates work internally', 'Use sampling instead of exact percentiles'], correctAnswer: 3, explanation: 'Building a custom percentile aggregate helps understand how ordered-set aggregates work. The state function collects values into an array. The final function sorts the array and interpolates the value at the requested position. This approach stores all values in memory, which is fine for moderate datasets. For very large datasets, approximate algorithms (like t-digest) are more memory-efficient.', codeSnippet: "-- Custom percentile aggregate:\nCREATE FUNCTION pctl_sfunc(state NUMERIC[], val NUMERIC)\nRETURNS NUMERIC[] AS $$\nBEGIN\n  RETURN array_append(state, val);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE FUNCTION pctl_ffunc(\n  state NUMERIC[], pctl NUMERIC\n) RETURNS NUMERIC AS $$\nDECLARE\n  sorted NUMERIC[];\n  idx NUMERIC;\n  lo INT; hi INT;\nBEGIN\n  SELECT array_agg(v ORDER BY v)\n  INTO sorted FROM unnest(state) v;\n\n  idx := 1 + pctl * (array_length(sorted, 1) - 1);\n  lo := FLOOR(idx);\n  hi := CEIL(idx);\n  IF lo = hi THEN RETURN sorted[lo]; END IF;\n  RETURN sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE my_percentile(NUMERIC, NUMERIC) (\n  sfunc = pctl_sfunc,\n  stype = NUMERIC[],\n  finalfunc = pctl_ffunc,\n  finalfunc_extra,\n  initcond = '{}'\n);", tags: ['advanced', 'custom-aggregates', 'percentile', 'implementation'] },
  { id: 'pg-advanced-l3-053', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'How do you use advisory locks for leader election?', options: ['Advisory locks cannot handle leader election', 'Use pg_try_advisory_lock with a well-known key for leader election — the first process to acquire the lock becomes the leader, other processes detect they are followers by getting false from pg_try_advisory_lock, and leadership transfers automatically when the leader disconnects', 'Use a separate consensus system like Raft', 'Use table-based locking for leader election'], correctAnswer: 0, explanation: 'Advisory locks provide a simple leader election mechanism for PostgreSQL-connected services. All candidates try to acquire the same advisory lock. Only one succeeds (the leader). Others can either block (pg_advisory_lock) or poll periodically (pg_try_advisory_lock). When the leader disconnects, the lock is released and another candidate can acquire it. This is simpler than consensus protocols but relies on PostgreSQL availability.', codeSnippet: "-- Leader election pattern:\nCREATE FUNCTION try_become_leader(group_name TEXT)\nRETURNS BOOLEAN AS $$\nDECLARE\n  lock_key BIGINT := hashtext(group_name);\nBEGIN\n  -- Try to acquire lock (non-blocking):\n  IF pg_try_advisory_lock(lock_key) THEN\n    RAISE NOTICE 'Became leader for %', group_name;\n    RETURN TRUE;\n  ELSE\n    RAISE NOTICE 'Another leader exists for %', group_name;\n    RETURN FALSE;\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Application loop:\n-- while true:\n--   if try_become_leader('scheduler'):\n--     run_scheduler_tasks()\n--   else:\n--     sleep(10)\n--     # retry\n\n-- Check who is the leader:\nSELECT l.pid, a.application_name, a.client_addr\nFROM pg_locks l\nJOIN pg_stat_activity a ON a.pid = l.pid\nWHERE l.locktype = 'advisory'\n  AND l.objid = hashtext('scheduler')::INT;", tags: ['advanced', 'advisory-locks', 'leader-election', 'distributed-systems'] },
  { id: 'pg-advanced-l3-054', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you compute the intersection of two geometries in PostGIS?', options: ['Use the && operator for intersection', 'Use ST_Intersects for computing intersection geometry', 'Use ST_Intersection(geometry_a, geometry_b) to compute the geometry that represents the shared area between two geometries — this returns a new geometry containing only the overlapping portion, useful for clipping and overlay analysis', 'Use ST_Union for intersection'], correctAnswer: 1, explanation: 'ST_Intersection returns the geometry that represents the shared space between two input geometries. Unlike ST_Intersects (which returns boolean), ST_Intersection returns the actual geometry of the overlap. This is fundamental for overlay analysis, clipping geometries to boundaries, and computing shared areas. The result geometry type depends on the inputs (two overlapping polygons produce a polygon, a line and polygon produce a line or point).', codeSnippet: "-- Intersection of two overlapping polygons:\nSELECT ST_AsText(\n  ST_Intersection(\n    ST_GeomFromText('POLYGON((0 0, 4 0, 4 4, 0 4, 0 0))'),\n    ST_GeomFromText('POLYGON((2 2, 6 2, 6 6, 2 6, 2 2))')\n  )\n); -- POLYGON((2 2, 4 2, 4 4, 2 4, 2 2))\n\n-- Clip features to a boundary:\nSELECT f.name,\n  ST_Intersection(f.geom, b.geom) AS clipped\nFROM features f, boundary b\nWHERE ST_Intersects(f.geom, b.geom);\n\n-- Area of overlap between zones:\nSELECT\n  z1.name, z2.name,\n  ST_Area(\n    ST_Intersection(z1.geom, z2.geom)::geography\n  ) / 1e6 AS overlap_km2\nFROM zones z1, zones z2\nWHERE z1.id < z2.id\n  AND ST_Intersects(z1.geom, z2.geom);", tags: ['advanced', 'postgis', 'st-intersection', 'overlay-analysis'] },
  { id: 'pg-advanced-l3-055', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you generate deterministic UUIDs (v5) with pgcrypto?', options: ['Use gen_random_uuid() which is always deterministic', 'UUID v5 is not supported in PostgreSQL', 'Use the uuid-ossp extension uuid_generate_v5(namespace, name) function — it generates a deterministic UUID by hashing a namespace UUID and a name string with SHA-1, producing the same UUID for the same input every time', 'Use digest() and cast to UUID'], correctAnswer: 2, explanation: 'UUID v5 creates deterministic (reproducible) UUIDs by hashing a namespace UUID and a name string using SHA-1. The same namespace + name always produces the same UUID. This is useful for creating stable identifiers from natural keys, deduplication, and idempotent operations. UUID v4 (gen_random_uuid) is random and different each time. Standard namespaces exist for DNS, URLs, OIDs, and X.500 names.', codeSnippet: "CREATE EXTENSION \"uuid-ossp\";\n\n-- UUID v5: deterministic from namespace + name\nSELECT uuid_generate_v5(\n  uuid_ns_dns(),       -- DNS namespace\n  'example.com'        -- name\n); -- Always: cfbff0d1-9375-5685-968c-48ce8b15ae17\n\n-- Same inputs = same UUID:\nSELECT uuid_generate_v5(uuid_ns_dns(), 'example.com')\n     = uuid_generate_v5(uuid_ns_dns(), 'example.com');\n-- true!\n\n-- Custom namespace for your app:\nSELECT uuid_generate_v5(\n  'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11'::UUID,\n  'user:alice@example.com'\n) AS stable_user_id;\n\n-- v4 for comparison (random, different each time):\nSELECT gen_random_uuid();\n-- Different every call", tags: ['advanced', 'pgcrypto', 'uuid-v5', 'deterministic-uuid'] },
  { id: 'pg-advanced-l3-056', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you use event triggers to implement a DDL rollback mechanism?', options: ['Event triggers automatically rollback DDL', 'Use pg_dump before each DDL statement', 'Create a ddl_command_end event trigger that records the DDL statement and generates its reverse (DROP for CREATE, CREATE for DROP) into a rollback log table — enabling a manual schema rollback capability by executing the reverse statements', 'PostgreSQL DDL is always transactional so rollback is built-in'], correctAnswer: 3, explanation: 'While PostgreSQL DDL is transactional (can be rolled back before COMMIT), event triggers can build a rollback journal for DDL that has already been committed. By capturing CREATE statements and storing corresponding DROP statements (and vice versa), you create a reversibility log. For ALTER TABLE operations, storing the previous state using pg_get_tabledef-style functions enables schema time-travel. This is useful for deployment rollback scenarios.', codeSnippet: "CREATE TABLE ddl_rollback_log (\n  id SERIAL PRIMARY KEY,\n  forward_ddl TEXT,\n  reverse_ddl TEXT,\n  applied_at TIMESTAMPTZ DEFAULT now(),\n  applied_by TEXT DEFAULT current_user\n);\n\nCREATE FUNCTION record_ddl_reverse()\nRETURNS event_trigger AS $$\nDECLARE\n  obj RECORD;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    IF obj.command_tag = 'CREATE TABLE' THEN\n      INSERT INTO ddl_rollback_log(forward_ddl, reverse_ddl)\n      VALUES (\n        current_query(),\n        format('DROP TABLE IF EXISTS %s', obj.object_identity)\n      );\n    ELSIF obj.command_tag = 'CREATE INDEX' THEN\n      INSERT INTO ddl_rollback_log(forward_ddl, reverse_ddl)\n      VALUES (\n        current_query(),\n        format('DROP INDEX IF EXISTS %s', obj.object_identity)\n      );\n    END IF;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'event-triggers', 'ddl-rollback', 'schema-versioning'] },
  { id: 'pg-advanced-l3-057', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a mode (most frequent value) aggregate?', options: ['Mode requires a subquery, not an aggregate', 'Use the built-in mode() function only', 'Create a custom aggregate that accumulates values and their counts in a state — the sfunc tracks frequencies using an hstore or JSONB accumulator, and the ffunc returns the value with the highest count', 'Mode aggregates are not possible in SQL'], correctAnswer: 0, explanation: 'PostgreSQL has a built-in mode() ordered-set aggregate, but building one demonstrates custom aggregate patterns. The state function maintains a frequency map (using JSONB, hstore, or array). The final function finds the key with the maximum count. This pattern applies to other frequency-based aggregates like most_common, top_n, or entropy calculations. The built-in mode() is more efficient for production use.', codeSnippet: "-- Built-in mode:\nSELECT mode()\n  WITHIN GROUP (ORDER BY department)\nFROM employees;\n\n-- Custom mode aggregate using JSONB:\nCREATE FUNCTION mode_sfunc(state JSONB, val TEXT)\nRETURNS JSONB AS $$\nBEGIN\n  IF val IS NULL THEN RETURN state; END IF;\n  IF state ? val THEN\n    RETURN jsonb_set(state, ARRAY[val],\n      to_jsonb((state->>val)::INT + 1));\n  ELSE\n    RETURN state || jsonb_build_object(val, 1);\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE FUNCTION mode_ffunc(state JSONB)\nRETURNS TEXT AS $$\nBEGIN\n  RETURN (\n    SELECT key FROM jsonb_each_text(state)\n    ORDER BY value::INT DESC LIMIT 1\n  );\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE my_mode(TEXT) (\n  sfunc = mode_sfunc,\n  stype = JSONB,\n  finalfunc = mode_ffunc,\n  initcond = '{}'\n);", tags: ['advanced', 'custom-aggregates', 'mode', 'frequency'] },
  { id: 'pg-advanced-l3-058', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you simplify complex geometries in PostGIS?', options: ['Delete vertices manually', 'Use ST_Simplify(geometry, tolerance) which applies the Douglas-Peucker algorithm to reduce the number of vertices while maintaining the overall shape — lower tolerance preserves more detail, higher tolerance creates simpler geometries with fewer points', 'Use ST_Reduce() function', 'Cast to a simpler geometry type'], correctAnswer: 1, explanation: 'ST_Simplify reduces geometry complexity by removing vertices that do not significantly affect the shape. The tolerance parameter controls how much simplification occurs (in CRS units). ST_SimplifyPreserveTopology is a safer variant that ensures the simplified geometry remains valid (no self-intersections). Simplification is essential for web mapping (reducing data transfer), visualization at different zoom levels, and reducing computation time for spatial operations.', codeSnippet: "-- Simplify a complex polygon:\nSELECT\n  ST_NPoints(boundary) AS original_points,\n  ST_NPoints(ST_Simplify(boundary, 0.001)) AS simplified,\n  ST_NPoints(ST_Simplify(boundary, 0.01)) AS more_simplified\nFROM districts;\n-- 5000 | 500 | 50\n\n-- Preserve topology (no self-intersections):\nSELECT ST_SimplifyPreserveTopology(boundary, 0.001)\nFROM districts;\n\n-- Simplify for different zoom levels:\nCREATE MATERIALIZED VIEW districts_simple AS\nSELECT id, name,\n  ST_SimplifyPreserveTopology(boundary, 0.001) AS geom_detail,\n  ST_SimplifyPreserveTopology(boundary, 0.01) AS geom_medium,\n  ST_SimplifyPreserveTopology(boundary, 0.1) AS geom_overview\nFROM districts;\n\n-- Use appropriate detail for zoom:\nSELECT name, ST_AsGeoJSON(geom_overview)\nFROM districts_simple; -- fast, less data", tags: ['advanced', 'postgis', 'st-simplify', 'geometry-simplification'] },
  { id: 'pg-advanced-l3-059', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Table Inheritance', question: 'How do you add a child table to an existing inheritance hierarchy?', options: ['Use ALTER TABLE child ADD PARENT parent', 'Use CREATE TABLE child INHERITS (parent) only at creation time', 'Use ALTER TABLE child INHERIT parent to add inheritance after the table is created — the child must already have all the same columns with compatible types as the parent, and you can also remove inheritance with ALTER TABLE child NO INHERIT parent', 'Inheritance relationships cannot be changed after creation'], correctAnswer: 2, explanation: 'ALTER TABLE ... INHERIT allows adding inheritance relationships to existing tables. The child table must already contain all columns that exist in the parent with compatible types. No data is moved — the child rows simply become visible through the parent. ALTER TABLE ... NO INHERIT removes the inheritance link without dropping the child table or its data. This is useful for managing partitions or reorganizing table hierarchies.', codeSnippet: "-- Existing tables:\nCREATE TABLE events (id SERIAL, ts TIMESTAMPTZ, data JSONB);\nCREATE TABLE click_events (id SERIAL, ts TIMESTAMPTZ, data JSONB, url TEXT);\n\n-- Add inheritance relationship:\nALTER TABLE click_events INHERIT events;\n-- Now SELECT * FROM events includes click_events rows\n\n-- Remove inheritance:\nALTER TABLE click_events NO INHERIT events;\n-- click_events still exists with its data\n-- but is no longer visible through events\n\n-- Useful for partition management:\n-- Detach old partition:\nALTER TABLE events_2023 NO INHERIT events;\n-- Archive or drop it independently\n\n-- Attach new partition:\nALTER TABLE events_2025 INHERIT events;\n\n-- Check inheritance:\nSELECT inhrelid::regclass AS child,\n       inhparent::regclass AS parent\nFROM pg_inherits;", tags: ['advanced', 'table-inheritance', 'alter-inherit', 'dynamic-hierarchy'] },
  { id: 'pg-advanced-l3-060', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you create and query multipart geometries in PostGIS?', options: ['Use arrays of geometries', 'Multipart geometries are not supported', 'Use ST_Collect or ST_Union to combine multiple geometries into MULTI types (MULTIPOINT, MULTILINESTRING, MULTIPOLYGON, GEOMETRYCOLLECTION) — these represent disconnected features that logically belong together, like an archipelago as a single MULTIPOLYGON', 'Use JSONB to store multiple geometries'], correctAnswer: 3, explanation: 'Multipart geometries represent multiple disconnected spatial features as a single geometry. A country with islands is stored as a MULTIPOLYGON. A river with branches can be a MULTILINESTRING. ST_Collect creates a geometry collection from multiple geometries. ST_Union merges overlapping geometries into a single unified geometry. Use ST_Dump to decompose multipart geometries into individual parts for per-feature analysis.', codeSnippet: "-- Create a MULTIPOLYGON:\nSELECT ST_Collect(\n  ST_GeomFromText('POLYGON((0 0,1 0,1 1,0 1,0 0))'),\n  ST_GeomFromText('POLYGON((2 2,3 2,3 3,2 3,2 2))')\n);\n-- MULTIPOLYGON(((0 0,1 0,...)),((2 2,3 2,...)))\n\n-- Aggregate into multipart:\nSELECT country,\n  ST_Collect(island_geom) AS all_islands\nFROM islands\nGROUP BY country;\n\n-- Decompose multipart into parts:\nSELECT\n  (ST_Dump(geom)).path[1] AS part_number,\n  (ST_Dump(geom)).geom AS single_polygon\nFROM countries\nWHERE name = 'Indonesia';\n\n-- Number of parts:\nSELECT name, ST_NumGeometries(geom) AS num_parts\nFROM countries;\n\n-- ST_Union merges overlapping parts:\nSELECT ST_Union(geom) FROM overlapping_zones;", tags: ['advanced', 'postgis', 'multipart', 'st-collect'] },
  { id: 'pg-advanced-l3-061', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you implement data masking using pgcrypto and views?', options: ['Use column-level permissions only', 'Use pgcrypto digest() to create masked versions of sensitive data — combine with views and row-level security to show hashed or partially obscured data to unprivileged users while full data is accessible to authorized users', 'Data masking requires a commercial extension', 'Use GRANT/REVOKE on individual columns'], correctAnswer: 0, explanation: 'Data masking combines pgcrypto hashing with PostgreSQL views and permissions to provide different data visibility levels. A masking view replaces sensitive columns with hashed or truncated versions. Users who need full data query the base table directly. This can be enhanced with row-level security policies for fine-grained access control. Common masking patterns include email truncation, SSN last-four-digits, and name hashing.', codeSnippet: "-- Base table with sensitive data:\nCREATE TABLE customers (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  email TEXT,\n  ssn TEXT,\n  phone TEXT\n);\n\n-- Masked view for general users:\nCREATE VIEW customers_masked AS\nSELECT\n  id,\n  LEFT(name, 1) || repeat('*', length(name)-1) AS name,\n  split_part(email, '@', 1) || '@***' AS email,\n  '***-**-' || RIGHT(ssn, 4) AS ssn,\n  '***-***-' || RIGHT(phone, 4) AS phone\nFROM customers;\n\n-- Grant access:\nGRANT SELECT ON customers_masked TO analyst_role;\n-- Full access for admin:\nGRANT ALL ON customers TO admin_role;\n\n-- Query masked view:\nSELECT * FROM customers_masked;\n-- id | name    | email       | ssn         | phone\n-- 1  | J***    | john@***    | ***-**-6789 | ***-***-1234", tags: ['advanced', 'pgcrypto', 'data-masking', 'views'] },
  { id: 'pg-advanced-l3-062', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'RULE System', question: 'How do you use rules for audit logging with DO ALSO?', options: ['DO ALSO is not a valid rule action', 'DO ALSO replaces the original operation', 'CREATE RULE ... DO ALSO executes additional statements alongside the original operation — unlike DO INSTEAD which replaces the operation, DO ALSO runs both the original DML and the additional statements, useful for audit logging without affecting the primary operation', 'DO ALSO only works with SELECT statements'], correctAnswer: 1, explanation: 'DO ALSO rules add extra actions to an operation without replacing it. For example, a DO ALSO rule on INSERT can log the insertion to an audit table while the original INSERT proceeds normally. Multiple DO ALSO rules can coexist. The original operation and all DO ALSO operations run within the same transaction. However, DO ALSO rules have the same pitfalls as other rules (COPY bypass, RETURNING issues) — triggers are generally preferred.', codeSnippet: "-- Audit logging with DO ALSO:\nCREATE RULE log_insert AS ON INSERT TO orders\n  DO ALSO\n  INSERT INTO orders_audit(order_id, action, ts, user_name)\n  VALUES (NEW.id, 'INSERT', now(), current_user);\n\nCREATE RULE log_update AS ON UPDATE TO orders\n  DO ALSO\n  INSERT INTO orders_audit(order_id, action, ts, user_name,\n    old_data, new_data)\n  VALUES (NEW.id, 'UPDATE', now(), current_user,\n    row_to_json(OLD), row_to_json(NEW));\n\nCREATE RULE log_delete AS ON DELETE TO orders\n  DO ALSO\n  INSERT INTO orders_audit(order_id, action, ts, user_name,\n    old_data)\n  VALUES (OLD.id, 'DELETE', now(), current_user,\n    row_to_json(OLD));\n\n-- Both operations happen:\nINSERT INTO orders(id, total) VALUES (1, 100);\n-- 1. Inserts into orders\n-- 2. Inserts into orders_audit (DO ALSO)", tags: ['advanced', 'rule-system', 'do-also', 'audit-logging'] },
  { id: 'pg-advanced-l3-063', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'How do you implement optimistic locking with advisory locks for long-running operations?', options: ['Optimistic locking does not use advisory locks', 'Use row versioning exclusively', 'Combine advisory locks with version columns — use pg_try_advisory_lock to check if a resource is being edited, and use a version column to detect concurrent modifications, providing both immediate feedback and data integrity protection', 'Use SELECT FOR UPDATE NOWAIT instead'], correctAnswer: 2, explanation: 'For long-running operations (like user editing a form), traditional pessimistic locks (SELECT FOR UPDATE) hold too long. A hybrid approach uses advisory locks for real-time "currently being edited" detection and version columns for final write conflict detection. The advisory lock signals to other users that someone is editing. The version check at save time catches any concurrent modifications that slipped through.', codeSnippet: "-- Table with version column:\nCREATE TABLE documents (\n  id INT PRIMARY KEY,\n  content TEXT,\n  version INT DEFAULT 1,\n  updated_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Start editing: try advisory lock\nCREATE FUNCTION start_editing(doc_id INT)\nRETURNS BOOLEAN AS $$\nBEGIN\n  IF pg_try_advisory_lock('documents'::regclass::INT, doc_id)\n  THEN\n    RETURN TRUE; -- got edit lock\n  ELSE\n    RETURN FALSE; -- someone else is editing\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Save: check version + release lock\nCREATE FUNCTION save_document(\n  doc_id INT, new_content TEXT, expected_version INT\n) RETURNS BOOLEAN AS $$\nBEGIN\n  UPDATE documents\n  SET content = new_content,\n      version = version + 1,\n      updated_at = now()\n  WHERE id = doc_id AND version = expected_version;\n\n  PERFORM pg_advisory_unlock(\n    'documents'::regclass::INT, doc_id);\n  RETURN FOUND;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'advisory-locks', 'optimistic-locking', 'versioning'] },
  { id: 'pg-advanced-l3-064', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you export PostGIS geometries to GeoJSON format?', options: ['Use pg_dump with GeoJSON format', 'Use COPY TO with JSON option', 'Use ST_AsGeoJSON(geometry) to convert individual geometries, or build a complete GeoJSON FeatureCollection using json_build_object and json_agg — GeoJSON is the standard format for web mapping libraries like Leaflet, MapboxGL, and OpenLayers', 'Install a separate GeoJSON extension'], correctAnswer: 3, explanation: 'ST_AsGeoJSON converts a PostGIS geometry to its GeoJSON representation. For complete GeoJSON output with properties, build Feature objects using json_build_object and aggregate them into a FeatureCollection with json_agg. This is the standard way to serve spatial data to web applications. GeoJSON always uses SRID 4326 (WGS84) coordinates. ST_AsGeoJSON supports precision control for coordinate decimal places.', codeSnippet: "-- Single geometry to GeoJSON:\nSELECT ST_AsGeoJSON(location) FROM places WHERE id = 1;\n-- {\"type\":\"Point\",\"coordinates\":[2.294,48.858]}\n\n-- Full FeatureCollection:\nSELECT json_build_object(\n  'type', 'FeatureCollection',\n  'features', json_agg(\n    json_build_object(\n      'type', 'Feature',\n      'geometry', ST_AsGeoJSON(location)::json,\n      'properties', json_build_object(\n        'id', id,\n        'name', name,\n        'category', category\n      )\n    )\n  )\n) AS geojson\nFROM places\nWHERE category = 'restaurant';\n\n-- With precision control (6 decimal places):\nSELECT ST_AsGeoJSON(location, 6) FROM places;", tags: ['advanced', 'postgis', 'geojson', 'web-mapping'] },
  { id: 'pg-advanced-l3-065', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a custom aggregate for computing standard deviation from scratch?', options: ['Standard deviation can only be computed with built-in functions', 'Use a subquery with mathematical formulas', 'Create an aggregate that tracks running sum, sum of squares, and count in its state — the final function computes sqrt((sum_sq/n) - (sum/n)^2) to derive the population standard deviation without storing all values', 'Use the stddev_pop() built-in exclusively'], correctAnswer: 0, explanation: 'An online (streaming) standard deviation aggregate maintains three values: count (n), sum of values (sum), and sum of squared values (sum_sq). These are sufficient to compute the population standard deviation using the formula sqrt(sum_sq/n - (sum/n)^2). This approach uses O(1) memory regardless of input size, unlike storing all values. This is how built-in stddev_pop works internally. The combinefunc is straightforward: add the components.', codeSnippet: "-- Online standard deviation aggregate:\nCREATE FUNCTION stddev_sfunc(\n  state NUMERIC[], val NUMERIC\n) RETURNS NUMERIC[] AS $$\nBEGIN\n  -- state: [count, sum, sum_of_squares]\n  RETURN ARRAY[\n    state[1] + 1,\n    state[2] + val,\n    state[3] + val * val\n  ];\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE FUNCTION stddev_ffunc(state NUMERIC[])\nRETURNS NUMERIC AS $$\nDECLARE\n  n NUMERIC := state[1];\n  mean NUMERIC;\n  variance NUMERIC;\nBEGIN\n  IF n < 2 THEN RETURN 0; END IF;\n  mean := state[2] / n;\n  variance := state[3] / n - mean * mean;\n  RETURN sqrt(variance);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE my_stddev(NUMERIC) (\n  sfunc = stddev_sfunc,\n  stype = NUMERIC[],\n  finalfunc = stddev_ffunc,\n  initcond = '{0,0,0}'\n);", tags: ['advanced', 'custom-aggregates', 'standard-deviation', 'streaming'] },
  { id: 'pg-advanced-l3-066', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you disable event triggers temporarily?', options: ['Use SET event_triggers = off', 'Drop and recreate the event trigger', 'Use ALTER EVENT TRIGGER trigger_name DISABLE to temporarily deactivate an event trigger, and ALTER EVENT TRIGGER trigger_name ENABLE to reactivate it — useful during migrations, maintenance, or when importing schema dumps that would otherwise trigger the event trigger', 'Event triggers cannot be disabled'], correctAnswer: 1, explanation: 'ALTER EVENT TRIGGER ... DISABLE/ENABLE works like ALTER TABLE ... DISABLE/ENABLE TRIGGER for regular triggers. When disabled, the event trigger exists in the catalog but does not fire. There is also ENABLE REPLICA (fires only during replication) and ENABLE ALWAYS (fires in all contexts). Only superusers can create, alter, or disable event triggers. Disabling during migrations prevents interference with schema import operations.', codeSnippet: "-- Disable event trigger:\nALTER EVENT TRIGGER enforce_naming DISABLE;\n\n-- Run migration without interference:\nCREATE TABLE TempImport (\n  ID INT, Data TEXT\n);  -- Would normally fail naming check\n\n-- Re-enable:\nALTER EVENT TRIGGER enforce_naming ENABLE;\n\n-- Check event trigger status:\nSELECT evtname, evtevent, evtowner::regrole,\n       evtenabled  -- O=origin, R=replica, A=always, D=disabled\nFROM pg_event_trigger;\n\n-- ENABLE modes:\nALTER EVENT TRIGGER trg ENABLE ALWAYS;\n-- Fires even during replication\nALTER EVENT TRIGGER trg ENABLE REPLICA;\n-- Fires only during replication\nALTER EVENT TRIGGER trg ENABLE;\n-- Normal mode (origin/local only)", tags: ['advanced', 'event-triggers', 'disable-enable', 'maintenance'] },
  { id: 'pg-advanced-l3-067', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you validate and repair invalid geometries in PostGIS?', options: ['PostGIS geometries are always valid', 'Use ST_Transform to fix invalid geometries', 'Use ST_IsValid(geometry) to check validity and ST_MakeValid(geometry) to repair — invalid geometries (self-intersecting polygons, collapsed features) can cause spatial functions to return wrong results or errors, so validation is important for data quality', 'Delete and recreate invalid geometries'], correctAnswer: 2, explanation: 'Invalid geometries violate OGC rules (e.g., polygon rings that cross themselves, duplicate vertices, zero-area polygons). Many PostGIS functions require valid input. ST_IsValid returns boolean. ST_IsValidReason explains what is wrong. ST_MakeValid attempts to repair the geometry by splitting self-intersecting rings, removing collapsed parts, etc. Always validate imported data and repair before spatial analysis.', codeSnippet: "-- Check validity:\nSELECT id, name,\n  ST_IsValid(geom) AS is_valid,\n  ST_IsValidReason(geom) AS reason\nFROM parcels\nWHERE NOT ST_IsValid(geom);\n-- id | name | is_valid | reason\n-- 42 | ...  | false    | Self-intersection at POINT(1.5 2.3)\n\n-- Repair invalid geometries:\nUPDATE parcels\nSET geom = ST_MakeValid(geom)\nWHERE NOT ST_IsValid(geom);\n\n-- Validate during insert:\nCREATE FUNCTION validate_geometry()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NOT ST_IsValid(NEW.geom) THEN\n    NEW.geom := ST_MakeValid(NEW.geom);\n    RAISE NOTICE 'Auto-repaired geometry for %', NEW.id;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Add CHECK constraint:\nALTER TABLE parcels\n  ADD CONSTRAINT valid_geom CHECK (ST_IsValid(geom));", tags: ['advanced', 'postgis', 'st-isvalid', 'st-makevalid'] },
  { id: 'pg-advanced-l3-068', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you use pgcrypto for generating TOTP-compatible secrets?', options: ['pgcrypto has built-in TOTP support', 'Use gen_random_bytes(20) to generate a 20-byte secret suitable for TOTP (Time-based One-Time Password) algorithms — encode it as base32 for compatibility with authenticator apps like Google Authenticator or Authy', 'TOTP requires a separate authentication service', 'Use crypt() for TOTP generation'], correctAnswer: 3, explanation: 'TOTP (RFC 6238) requires a shared secret, typically 20 bytes (160 bits). gen_random_bytes(20) produces a cryptographically random secret. This secret is encoded as base32 for QR code generation and authenticator app input. The actual TOTP code generation (HMAC-SHA1 of time-based counter) can be computed in PL/pgSQL using pgcrypto hmac() function, though most implementations handle this in application code.', codeSnippet: "-- Generate TOTP secret:\nCREATE FUNCTION generate_totp_secret()\nRETURNS TEXT AS $$\nDECLARE\n  raw_bytes BYTEA := gen_random_bytes(20);\n  base32_chars TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';\n  result TEXT := '';\n  bits BIT VARYING;\n  chunk INT;\nBEGIN\n  -- Convert bytes to base32 encoding\n  bits := raw_bytes::BIT(160);\n  FOR i IN 0..31 LOOP\n    chunk := substring(bits, i*5+1, 5)::INT;\n    result := result || substr(base32_chars, chunk+1, 1);\n  END LOOP;\n  RETURN result;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Store for user:\nUPDATE users\nSET totp_secret = generate_totp_secret()\nWHERE id = 1;\n\n-- Generate provisioning URI for QR code:\nSELECT format(\n  'otpauth://totp/%s?secret=%s&issuer=%s',\n  email, totp_secret, 'MyApp'\n) FROM users WHERE id = 1;", tags: ['advanced', 'pgcrypto', 'totp', 'two-factor-auth'] },
  { id: 'pg-advanced-l3-069', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Table Inheritance', question: 'How do you use multiple inheritance in PostgreSQL?', options: ['Multiple inheritance is not supported', 'Only single inheritance is allowed', 'A child table can inherit from multiple parent tables using INHERITS (parent1, parent2) — it receives columns from all parents, with duplicate column names merged if the types are compatible, creating a combined structure', 'Use foreign keys to simulate multiple inheritance'], correctAnswer: 0, explanation: 'PostgreSQL supports multiple inheritance where a child inherits from several parents. If parents have columns with the same name, the types must match and the columns are merged into one. CHECK constraints from all parents are inherited. This is useful for mixin-style patterns where different aspects of a table are defined separately. However, the same limitations apply: no cross-hierarchy unique constraints or foreign keys.', codeSnippet: "-- Parent tables define different aspects:\nCREATE TABLE timestamped (\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now()\n);\n\nCREATE TABLE soft_deletable (\n  deleted_at TIMESTAMPTZ,\n  is_active BOOLEAN DEFAULT TRUE\n);\n\nCREATE TABLE auditable (\n  created_by TEXT DEFAULT current_user,\n  updated_by TEXT DEFAULT current_user\n);\n\n-- Child inherits from multiple parents:\nCREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  customer_id INT,\n  total NUMERIC\n) INHERITS (timestamped, soft_deletable, auditable);\n\n-- orders has: id, customer_id, total,\n-- created_at, updated_at, deleted_at,\n-- is_active, created_by, updated_by\n\n\\d orders  -- shows all inherited columns", tags: ['advanced', 'table-inheritance', 'multiple-inheritance', 'mixins'] },
  { id: 'pg-advanced-l3-070', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you generate heatmaps and density analysis with PostGIS?', options: ['Use CSS styling on point data', 'PostGIS does not support density analysis', 'Use ST_HexagonGrid or ST_SquareGrid to create grid cells, then count points per cell with ST_Contains — alternatively use kernel density estimation by buffering points and computing intersection weights for smooth heatmap surfaces', 'Use a separate analytics tool'], correctAnswer: 1, explanation: 'Heatmap generation in PostGIS involves counting or aggregating point density within grid cells. ST_HexagonGrid (PG 15+) creates hexagonal bins. ST_SquareGrid creates square bins. Points are assigned to cells using ST_Contains or ST_Within. For smoother surfaces, kernel density estimation buffers each point, computes overlapping buffer areas, and sums weights. The results can be exported as GeoJSON for visualization with web mapping libraries.', codeSnippet: "-- Hexagonal binning for heatmap:\nWITH grid AS (\n  SELECT (ST_HexagonGrid(\n    100,  -- 100 meter cell size\n    ST_SetSRID(ST_Extent(location), 32632)\n  )).*\n  FROM incidents\n)\nSELECT g.geom, COUNT(i.id) AS incident_count\nFROM grid g\nLEFT JOIN incidents i\n  ON ST_Contains(g.geom, ST_Transform(i.location, 32632))\nGROUP BY g.geom\nHAVING COUNT(i.id) > 0;\n\n-- Square grid density:\nWITH grid AS (\n  SELECT (ST_SquareGrid(\n    0.01,  -- ~1km in degrees\n    ST_SetSRID(ST_Extent(location), 4326)\n  )).*\n  FROM incidents\n)\nSELECT g.geom, COUNT(i.id) AS density\nFROM grid g\nLEFT JOIN incidents i ON ST_Contains(g.geom, i.location)\nGROUP BY g.geom;", tags: ['advanced', 'postgis', 'heatmap', 'density-analysis'] },
  { id: 'pg-advanced-l3-071', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you handle NULL values in custom aggregate functions?', options: ['By default PostgreSQL skips NULL input rows for aggregates — the sfunc is not called for NULL inputs, but you can override this behavior by not marking the sfunc as STRICT and handling NULLs explicitly in the function body', 'NULL values crash custom aggregates', 'NULL values are converted to zero automatically', 'Use COALESCE before passing values to aggregates'], correctAnswer: 2, explanation: 'PostgreSQL aggregate NULL handling: by default, rows with NULL input are skipped (the sfunc is not called). If sfunc is declared STRICT, it is also skipped when any argument is NULL. If the state itself becomes NULL (when initcond is not set and first row is NULL), the aggregate may return NULL. To count NULLs, do not use STRICT and handle NULLs explicitly in the sfunc. The built-in count(*) is a special case that counts all rows including NULLs.', codeSnippet: "-- Default: NULL inputs are skipped\nCREATE AGGREGATE my_sum(NUMERIC) (\n  sfunc = numeric_add,\n  stype = NUMERIC,\n  initcond = '0'\n);\nSELECT my_sum(x) FROM (VALUES (1),(NULL),(3)) t(x);\n-- Result: 4 (NULL skipped)\n\n-- Count non-NULL and NULL separately:\nCREATE FUNCTION null_counter_sfunc(\n  state INT[], val ANYELEMENT\n) RETURNS INT[] AS $$\nBEGIN\n  IF val IS NULL THEN\n    RETURN ARRAY[state[1], state[2] + 1];\n  ELSE\n    RETURN ARRAY[state[1] + 1, state[2]];\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE null_stats(ANYELEMENT) (\n  sfunc = null_counter_sfunc,\n  stype = INT[],\n  initcond = '{0,0}'\n  -- NOT STRICT: receive NULL inputs\n);", tags: ['advanced', 'custom-aggregates', 'null-handling', 'strict'] },
  { id: 'pg-advanced-l3-072', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you store and query 3D geometries in PostGIS?', options: ['PostGIS only supports 2D geometries', 'Use a separate Z column', 'Specify geometry type with Z dimension — GEOMETRY(PointZ, 4326) or GEOMETRY(PolygonZ, 4326) stores 3D coordinates, with functions like ST_3DDistance, ST_3DIntersects, and ST_3DLength for true 3D spatial analysis', 'Store elevation as an attribute only'], correctAnswer: 3, explanation: 'PostGIS supports 3D (XYZ) and 4D (XYZM) geometries. The Z coordinate typically represents elevation or height. 3D spatial functions (ST_3DDistance, ST_3DIntersects, ST_3DDWithin) consider the Z dimension in calculations. 2D functions (ST_Distance, ST_Intersects) ignore Z. GiST indexes support 3D with the nd_geometry_ops operator class. 3D is essential for applications like underground utility mapping, aviation, and building floor analysis.', codeSnippet: "-- 3D point:\nCREATE TABLE sensor_locations (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  location GEOMETRY(PointZ, 4326)\n);\n\nINSERT INTO sensor_locations (name, location)\nVALUES ('Roof sensor',\n  ST_SetSRID(ST_MakePoint(13.4, 52.5, 50.0), 4326));\n\n-- 3D distance (considers elevation):\nSELECT ST_3DDistance(\n  ST_MakePoint(0, 0, 0),\n  ST_MakePoint(3, 4, 5)\n); -- ~7.07 (not 5.0 as in 2D)\n\n-- 2D distance (ignores Z):\nSELECT ST_Distance(\n  ST_MakePoint(0, 0, 0),\n  ST_MakePoint(3, 4, 5)\n); -- 5.0\n\n-- Extract Z value:\nSELECT ST_Z(location) AS elevation\nFROM sensor_locations;", tags: ['advanced', 'postgis', '3d-geometry', 'elevation'] },
  { id: 'pg-advanced-l3-073', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you create an event trigger that prevents schema changes by non-superusers?', options: ['Use REVOKE CREATE on the schema', 'Use ALTER SCHEMA SET READONLY', 'Create a ddl_command_start event trigger that checks current_user privileges and raises an exception if the user is not a superuser or designated DBA — this provides a database-wide DDL restriction beyond individual privilege settings', 'Event triggers cannot restrict based on user'], correctAnswer: 0, explanation: 'Event triggers can enforce schema protection beyond what GRANT/REVOKE provides. By checking the session user in a ddl_command_start trigger, you can prevent DDL from specific users, during specific time windows, or for specific object types. This is a defense-in-depth measure — even if a user has DDL privileges, the event trigger can add additional restrictions. Be careful not to lock yourself out; superuser exemptions are important.', codeSnippet: "CREATE FUNCTION restrict_ddl()\nRETURNS event_trigger AS $$\nDECLARE\n  allowed_users TEXT[] := ARRAY['dba', 'migration_user'];\nBEGIN\n  -- Skip for superusers:\n  IF current_setting('is_superuser') = 'on' THEN\n    RETURN;\n  END IF;\n\n  -- Check if user is allowed:\n  IF NOT (current_user = ANY(allowed_users)) THEN\n    RAISE EXCEPTION\n      'User % is not allowed to perform DDL. Contact DBA.',\n      current_user;\n  END IF;\n\n  -- Optionally restrict by time:\n  IF extract(hour from now()) BETWEEN 9 AND 17 THEN\n    RAISE EXCEPTION\n      'DDL changes blocked during business hours (9-17)';\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER restrict_ddl_access\n  ON ddl_command_start\n  EXECUTE FUNCTION restrict_ddl();", tags: ['advanced', 'event-triggers', 'ddl-restriction', 'access-control'] },
  { id: 'pg-advanced-l3-074', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Advisory Locks', question: 'How do you handle advisory lock deadlocks?', options: ['Advisory locks never deadlock', 'Advisory locks deadlock detection is automatic — PostgreSQL detects advisory lock deadlocks and aborts one of the conflicting transactions with a deadlock_detected error, just like it does for regular row and table locks', 'Deadlocks require manual intervention', 'Use timeouts to prevent deadlocks'], correctAnswer: 1, explanation: 'PostgreSQL deadlock detector handles advisory locks just like other locks. If session A holds lock 1 and waits for lock 2, while session B holds lock 2 and waits for lock 1, PostgreSQL will detect the cycle and abort one session with ERROR: deadlock detected. The deadlock_timeout setting (default 1s) controls how long to wait before checking for deadlocks. Using pg_try_advisory_lock (non-blocking) avoids deadlocks entirely.', codeSnippet: "-- Deadlock scenario:\n-- Session A:           Session B:\n-- pg_advisory_lock(1)  pg_advisory_lock(2)\n-- pg_advisory_lock(2)  pg_advisory_lock(1)\n--  ^^ DEADLOCK!         ^^ DEADLOCK!\n\n-- One session gets:\n-- ERROR: deadlock detected\n-- DETAIL: Process 1234 waits for advisory lock;\n--   blocked by process 5678.\n--   Process 5678 waits for advisory lock;\n--   blocked by process 1234.\n\n-- Prevention: always lock in consistent order:\n-- Always lock lower key first:\nCREATE FUNCTION safe_lock_pair(key1 BIGINT, key2 BIGINT)\nRETURNS VOID AS $$\nBEGIN\n  IF key1 < key2 THEN\n    PERFORM pg_advisory_lock(key1);\n    PERFORM pg_advisory_lock(key2);\n  ELSE\n    PERFORM pg_advisory_lock(key2);\n    PERFORM pg_advisory_lock(key1);\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Or use try-lock to avoid blocking:\nSELECT pg_try_advisory_lock(1)\n   AND pg_try_advisory_lock(2);", tags: ['advanced', 'advisory-locks', 'deadlock', 'prevention'] },
  { id: 'pg-advanced-l3-075', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you perform voronoi diagram and Delaunay triangulation in PostGIS?', options: ['These operations require external GIS software', 'Use ST_VoronoiPolygons(geometry) to create regions where each point is closest to a specific input point, and ST_DelaunayTriangles(geometry) to create a triangulated irregular network — both are fundamental for spatial analysis, interpolation, and territory assignment', 'Only commercial GIS extensions support these', 'Use recursive CTEs for triangulation'], correctAnswer: 2, explanation: 'Voronoi diagrams partition space so every point in a region is closer to one input point than any other — useful for service area delineation, nearest-facility assignment, and spatial interpolation. Delaunay triangulation creates optimal triangles from point sets — useful for terrain modeling (TIN), spatial interpolation, and mesh generation. Both functions operate on collections of points (MULTIPOINT or GEOMETRYCOLLECTION).', codeSnippet: "-- Voronoi diagram (service areas):\nWITH points AS (\n  SELECT ST_Collect(location) AS geom\n  FROM fire_stations\n)\nSELECT (ST_Dump(\n  ST_VoronoiPolygons(geom)\n)).geom AS service_area\nFROM points;\n\n-- Clip voronoi to city boundary:\nWITH points AS (\n  SELECT ST_Collect(location) AS geom FROM stations\n),\nvoronoi AS (\n  SELECT (ST_Dump(ST_VoronoiPolygons(geom))).geom\n  FROM points\n)\nSELECT ST_Intersection(v.geom, c.boundary)\nFROM voronoi v, city_boundary c;\n\n-- Delaunay triangulation:\nSELECT (ST_Dump(\n  ST_DelaunayTriangles(\n    ST_Collect(location)\n  )\n)).geom AS triangle\nFROM survey_points;", tags: ['advanced', 'postgis', 'voronoi', 'delaunay'] },
  { id: 'pg-advanced-l3-076', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'RULE System', question: 'How do you use conditional rules with WHERE clauses?', options: ['Rules do not support WHERE clauses', 'WHERE clauses in rules filter the output', 'CREATE RULE ... WHERE (condition) DO ... restricts the rule to fire only when the condition is met — the condition can reference NEW and OLD, allowing different rule actions for different data patterns on the same operation', 'Use CASE inside the rule action instead'], correctAnswer: 3, explanation: 'Conditional rules use WHERE clauses to match specific patterns. Multiple rules on the same event with different WHERE conditions create branching behavior. If no rule matches, the default action occurs. This is more declarative than trigger-based conditional logic but has the same limitations as other rules. The condition is evaluated before the rule action is applied to the query rewrite.', codeSnippet: "-- Route inserts based on status:\nCREATE RULE route_pending AS ON INSERT TO orders\n  WHERE NEW.status = 'pending'\n  DO ALSO\n  INSERT INTO pending_queue(order_id, created_at)\n  VALUES (NEW.id, now());\n\nCREATE RULE route_urgent AS ON INSERT TO orders\n  WHERE NEW.priority = 'urgent'\n  DO ALSO\n  INSERT INTO urgent_alerts(order_id, message)\n  VALUES (NEW.id, 'Urgent order received');\n\n-- Prevent deletion of shipped orders:\nCREATE RULE no_delete_shipped AS ON DELETE TO orders\n  WHERE OLD.status = 'shipped'\n  DO INSTEAD NOTHING;\n\n-- Redirect based on value:\nCREATE RULE archive_old AS ON DELETE TO events\n  WHERE OLD.created_at < now() - interval '1 year'\n  DO INSTEAD\n  INSERT INTO events_archive SELECT OLD.*;", tags: ['advanced', 'rule-system', 'conditional-rules', 'where-clause'] },
  { id: 'pg-advanced-l3-077', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a top-N aggregate that returns the N largest values?', options: ['Use ORDER BY and LIMIT instead of an aggregate', 'Create a custom aggregate that maintains a sorted array of the top N values in its state — the sfunc inserts new values and trims to N, and the ffunc returns the final sorted array, enabling per-group top-N queries as an aggregate', 'Top-N requires window functions only', 'Use DISTINCT ON for top-N'], correctAnswer: 0, explanation: 'A top-N aggregate maintains a bounded-size sorted array. Each sfunc call checks if the new value should enter the top-N, inserting it in sorted position and removing the smallest if the array exceeds N. This is useful when you need top-N per group (which is awkward with LIMIT). The aggregate state size is bounded by N, making it memory-efficient. This pattern implements a min-heap or sorted array as the aggregate state.', codeSnippet: "-- Top-N aggregate:\nCREATE FUNCTION topn_sfunc(\n  state NUMERIC[], val NUMERIC, n INT\n) RETURNS NUMERIC[] AS $$\nBEGIN\n  IF val IS NULL THEN RETURN state; END IF;\n  state := array_append(state, val);\n  -- Sort descending and keep top N:\n  SELECT array_agg(v ORDER BY v DESC)\n  INTO state\n  FROM (\n    SELECT unnest(state) AS v\n    ORDER BY v DESC\n    LIMIT n\n  ) sub;\n  RETURN state;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE top_n(NUMERIC, INT) (\n  sfunc = topn_sfunc,\n  stype = NUMERIC[],\n  initcond = '{}'\n);\n\n-- Top 3 salaries per department:\nSELECT department,\n  top_n(salary, 3) AS top_3_salaries\nFROM employees\nGROUP BY department;", tags: ['advanced', 'custom-aggregates', 'top-n', 'bounded-aggregate'] },
  { id: 'pg-advanced-l3-078', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you implement geofencing with PostGIS?', options: ['Use application-level coordinate checks', 'Use triggers and ST_Contains to check if a point enters or exits defined polygon zones — combine with LISTEN/NOTIFY to send real-time alerts when tracked objects cross geofence boundaries, implementing geofencing entirely within the database', 'Geofencing requires a dedicated geofencing service', 'Use simple latitude/longitude range checks'], correctAnswer: 1, explanation: 'Geofencing checks whether a moving point (vehicle, device) is inside or outside defined geographic areas. PostGIS implements this with ST_Contains/ST_Within for the spatial check, triggers for detecting boundary crossings when location updates occur, and LISTEN/NOTIFY for real-time alerts to applications. Spatial indexes make the checks fast enough for real-time use. The trigger compares old and new containment status to detect enter/exit events.', codeSnippet: "-- Geofence zones:\nCREATE TABLE geofences (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  boundary GEOMETRY(Polygon, 4326)\n);\nCREATE INDEX ON geofences USING gist(boundary);\n\n-- Device tracking:\nCREATE TABLE device_locations (\n  device_id INT PRIMARY KEY,\n  location GEOMETRY(Point, 4326),\n  updated_at TIMESTAMPTZ\n);\n\n-- Geofence trigger:\nCREATE FUNCTION check_geofences()\nRETURNS TRIGGER AS $$\nDECLARE\n  fence RECORD;\nBEGIN\n  FOR fence IN SELECT * FROM geofences LOOP\n    IF ST_Contains(fence.boundary, NEW.location)\n       AND NOT ST_Contains(fence.boundary, OLD.location) THEN\n      PERFORM pg_notify('geofence',\n        json_build_object(\n          'event', 'enter', 'device', NEW.device_id,\n          'fence', fence.name\n        )::TEXT);\n    ELSIF NOT ST_Contains(fence.boundary, NEW.location)\n       AND ST_Contains(fence.boundary, OLD.location) THEN\n      PERFORM pg_notify('geofence',\n        json_build_object(\n          'event', 'exit', 'device', NEW.device_id,\n          'fence', fence.name\n        )::TEXT);\n    END IF;\n  END LOOP;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'postgis', 'geofencing', 'real-time'] },
  { id: 'pg-advanced-l3-079', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you implement row-level encryption where different rows use different keys?', options: ['Use a single master key for all rows', 'Row-level encryption is not possible', 'Store a key identifier per row and use pgp_sym_encrypt with the corresponding key — different users or data categories can have different encryption keys, enabling fine-grained access control where compromise of one key does not expose all data', 'Use row-level security instead of encryption'], correctAnswer: 2, explanation: 'Per-row encryption keys enable data compartmentalization. Each row (or group of rows) is encrypted with a different key, so compromising one key only exposes that subset of data. The key_id column references a key management system. Keys can be rotated per-group. This pattern is used in multi-tenant systems where each tenant has a separate encryption key, and in healthcare where patient data has per-patient keys.', codeSnippet: "-- Table with per-row key reference:\nCREATE TABLE medical_records (\n  id SERIAL PRIMARY KEY,\n  patient_id INT,\n  key_id TEXT,  -- references key management\n  diagnosis_encrypted BYTEA,\n  notes_encrypted BYTEA\n);\n\n-- Insert with patient-specific key:\nCREATE FUNCTION encrypt_record(\n  p_patient_id INT,\n  p_diagnosis TEXT,\n  p_notes TEXT\n) RETURNS VOID AS $$\nDECLARE\n  enc_key TEXT;\n  kid TEXT;\nBEGIN\n  -- Get key from key management:\n  SELECT key_value, key_identifier INTO enc_key, kid\n  FROM key_store WHERE patient_id = p_patient_id;\n\n  INSERT INTO medical_records(\n    patient_id, key_id,\n    diagnosis_encrypted, notes_encrypted\n  ) VALUES (\n    p_patient_id, kid,\n    pgp_sym_encrypt(p_diagnosis, enc_key),\n    pgp_sym_encrypt(p_notes, enc_key)\n  );\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Compromising key for patient 1\n-- does NOT expose patient 2's data", tags: ['advanced', 'pgcrypto', 'row-level-encryption', 'key-management'] },
  { id: 'pg-advanced-l3-080', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create a JSON aggregation aggregate beyond json_agg?', options: ['json_agg covers all JSON aggregation needs', 'Use string concatenation for custom JSON', 'Create a custom aggregate that builds structured JSON during aggregation — accumulating key-value pairs, nested objects, or conditional fields in the sfunc, and producing a final formatted JSON document in the ffunc', 'Custom JSON aggregates require a JSON library'], correctAnswer: 3, explanation: 'While json_agg and jsonb_agg handle basic array aggregation, custom aggregates can build complex JSON structures. For example, aggregating into a nested JSON object with computed fields, conditional inclusion of properties, or hierarchical structures. The state can be JSONB, accumulating data with jsonb_set, || (concatenation), and jsonb_build_object. The final function can restructure or filter the accumulated state.', codeSnippet: "-- Custom: aggregate into key-value object\nCREATE FUNCTION kv_sfunc(\n  state JSONB, key TEXT, val JSONB\n) RETURNS JSONB AS $$\nBEGIN\n  RETURN state || jsonb_build_object(key, val);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE FUNCTION kv_combine(a JSONB, b JSONB)\nRETURNS JSONB AS $$\n  SELECT a || b;\n$$ LANGUAGE sql;\n\nCREATE AGGREGATE json_object_agg_custom(TEXT, JSONB) (\n  sfunc = kv_sfunc,\n  stype = JSONB,\n  combinefunc = kv_combine,\n  initcond = '{}'\n);\n\n-- Build nested config from rows:\nSELECT json_object_agg_custom(\n  setting_key,\n  to_jsonb(setting_value)\n) FROM app_settings;\n-- {\"theme\": \"dark\", \"lang\": \"en\", \"limit\": \"100\"}\n\n-- Built-in alternative (PG 16+):\nSELECT jsonb_object_agg(key, value) FROM settings;", tags: ['advanced', 'custom-aggregates', 'json-aggregation', 'jsonb'] },
  { id: 'pg-advanced-l3-081', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you use PostGIS for network analysis with pgRouting?', options: ['PostGIS includes routing functions by default', 'pgRouting is a separate extension that adds graph algorithms to PostGIS — it provides Dijkstra, A*, and other shortest-path algorithms that work on road network data stored in PostGIS, enabling route planning, isochrone generation, and service area analysis', 'Use recursive CTEs for routing', 'Routing requires an external service like Google Maps'], correctAnswer: 0, explanation: 'pgRouting extends PostGIS with network analysis algorithms. It operates on a graph representation of a road network (edges with costs, start/end nodes). Key functions include pgr_dijkstra (shortest path), pgr_astar (A* heuristic), pgr_drivingDistance (isochrone/service area), and pgr_TSP (traveling salesman). Road data from OpenStreetMap can be imported with osm2pgrouting. Results are joined back to geometry for visualization.', codeSnippet: "CREATE EXTENSION pgrouting;\n\n-- Road network table:\nCREATE TABLE roads (\n  id SERIAL PRIMARY KEY,\n  source INT,\n  target INT,\n  cost FLOAT,\n  reverse_cost FLOAT,\n  geom GEOMETRY(LineString, 4326)\n);\n\n-- Build topology:\nSELECT pgr_createTopology('roads', 0.00001, 'geom');\n\n-- Shortest path (Dijkstra):\nSELECT r.id, r.geom, d.cost\nFROM pgr_dijkstra(\n  'SELECT id, source, target, cost, reverse_cost FROM roads',\n  1,    -- start node\n  100   -- end node\n) d\nJOIN roads r ON d.edge = r.id;\n\n-- Driving distance (isochrone):\nSELECT *\nFROM pgr_drivingDistance(\n  'SELECT id, source, target, cost FROM roads',\n  1,     -- start node\n  10.0   -- max cost (distance/time)\n);", tags: ['advanced', 'postgis', 'pgrouting', 'network-analysis'] },
  { id: 'pg-advanced-l3-082', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Table Inheritance', question: 'How do you add CHECK constraints in an inheritance hierarchy?', options: ['CHECK constraints must be identical across all tables', 'Child tables cannot have CHECK constraints', 'CHECK constraints on parent tables are automatically inherited by children — children can add additional constraints, and you can use NO INHERIT to prevent a constraint from being inherited, allowing per-table constraint customization', 'Use triggers instead of constraints in hierarchies'], correctAnswer: 1, explanation: 'CHECK constraints on parent tables are inherited by all children by default. This ensures data validity across the hierarchy. Children can add their own additional constraints. The NO INHERIT option prevents a specific constraint from propagating to children. NOT NULL constraints are also inherited. This is useful for enforcing common rules (like positive prices) at the parent level while allowing specific rules (like type-specific ranges) at the child level.', codeSnippet: "-- Parent with inherited constraint:\nCREATE TABLE products (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  price NUMERIC CHECK (price >= 0),  -- inherited\n  stock INT CHECK (stock >= 0)        -- inherited\n);\n\n-- Child inherits all parent constraints:\nCREATE TABLE electronics (\n  warranty_months INT CHECK (warranty_months > 0),\n  voltage TEXT\n) INHERITS (products);\n-- electronics has: price >= 0, stock >= 0,\n-- PLUS warranty_months > 0\n\n-- NO INHERIT constraint:\nALTER TABLE products\n  ADD CONSTRAINT parent_only_check\n  CHECK (name != 'test') NO INHERIT;\n-- This constraint applies ONLY to products,\n-- not to electronics\n\n-- Check inherited constraints:\nSELECT conname, conrelid::regclass, coninhcount\nFROM pg_constraint\nWHERE conrelid = 'electronics'::regclass;", tags: ['advanced', 'table-inheritance', 'check-constraints', 'no-inherit'] },
  { id: 'pg-advanced-l3-083', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'pgcrypto', question: 'How do you securely compare encrypted values without decryption?', options: ['Always decrypt and compare in plaintext', 'Use = operator on encrypted bytea columns', 'Use HMAC-based blind indexes for equality comparison, or order-preserving encryption for range queries — since pgp_sym_encrypt produces different ciphertext each time (due to random session keys), direct comparison of encrypted values is not possible', 'Encrypted values cannot be compared at all'], correctAnswer: 2, explanation: 'PGP encryption is randomized — encrypting the same value twice produces different ciphertext. This prevents direct comparison of encrypted columns. Solutions: 1) Blind index (HMAC) for equality checks, 2) Deterministic encryption (same plaintext = same ciphertext) using raw encrypt() with a fixed IV (less secure), 3) Order-preserving encryption schemes for range queries (specialized). Each approach trades security for functionality.', codeSnippet: "-- Problem: PGP encryption is randomized\nSELECT pgp_sym_encrypt('hello', 'key')\n     = pgp_sym_encrypt('hello', 'key');\n-- FALSE! Different ciphertext each time\n\n-- Solution 1: HMAC blind index (equality only)\nCREATE TABLE users (\n  id SERIAL PRIMARY KEY,\n  email_encrypted BYTEA,\n  email_hmac BYTEA  -- for equality search\n);\n\nINSERT INTO users (email_encrypted, email_hmac)\nVALUES (\n  pgp_sym_encrypt('alice@example.com', 'enc_key'),\n  hmac('alice@example.com', 'hmac_key', 'sha256')\n);\n\n-- Search by HMAC (fast, indexed):\nSELECT pgp_sym_decrypt(email_encrypted, 'enc_key')\nFROM users\nWHERE email_hmac = hmac('alice@example.com', 'hmac_key', 'sha256');\n\n-- Solution 2: Deterministic (less secure):\nSELECT encrypt(\n  'hello'::bytea, 'key'::bytea, 'aes-ecb'\n); -- Same input = same output (but less secure)", tags: ['advanced', 'pgcrypto', 'encrypted-comparison', 'blind-index'] },
  { id: 'pg-advanced-l3-084', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you perform raster analysis in PostGIS?', options: ['PostGIS only supports vector data', 'Use the PostGIS Raster extension (included with PostGIS) to store and analyze raster (gridded) data — raster data represents continuous surfaces like elevation, temperature, or satellite imagery as a grid of pixel values, queryable alongside vector data', 'Raster analysis requires separate GIS software', 'Convert all raster data to vector first'], correctAnswer: 3, explanation: 'PostGIS Raster stores gridded data as raster type columns. Each raster has one or more bands (e.g., RGB, elevation). Functions include ST_Value (pixel value at a point), ST_Clip (clip raster to polygon), ST_MapAlgebra (raster math), and ST_AsTIFF/ST_AsPNG (export). Raster data can be loaded with raster2pgsql tool. Combining raster and vector analysis (e.g., average elevation within a polygon) is a powerful PostGIS capability.', codeSnippet: "-- Load raster data:\n-- raster2pgsql -s 4326 -I -M elevation.tif public.dem | psql\n\n-- Get elevation at a point:\nSELECT ST_Value(\n  rast,\n  ST_SetSRID(ST_MakePoint(13.4, 52.5), 4326)\n) AS elevation\nFROM dem\nWHERE ST_Intersects(\n  rast,\n  ST_SetSRID(ST_MakePoint(13.4, 52.5), 4326)\n);\n\n-- Average elevation within a polygon:\nSELECT (ST_SummaryStats(\n  ST_Clip(r.rast, d.boundary)\n)).mean AS avg_elevation\nFROM dem r, districts d\nWHERE d.name = 'Central'\n  AND ST_Intersects(r.rast, d.boundary);\n\n-- Raster algebra (slope from elevation):\nSELECT ST_Slope(rast) FROM dem;", tags: ['advanced', 'postgis', 'raster', 'gridded-data'] },
  { id: 'pg-advanced-l3-085', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Event Triggers', question: 'How do you use event triggers to maintain a data dictionary?', options: ['Use pg_catalog views only', 'Run a daily script to update documentation', 'Create ddl_command_end event triggers that automatically update a custom data_dictionary table whenever tables, columns, or functions are created or modified — keeping a human-readable catalog synchronized with the actual schema', 'Data dictionaries cannot be automated'], correctAnswer: 0, explanation: 'An automated data dictionary uses event triggers to maintain metadata alongside PostgreSQL system catalogs. When DDL is executed, the trigger extracts details (table descriptions, column comments, data types) and stores them in a queryable documentation table. This supplements pg_catalog with domain-specific metadata like data stewards, sensitivity classifications, and business definitions that are not captured by standard catalog columns.', codeSnippet: "CREATE TABLE data_dictionary (\n  object_type TEXT,\n  schema_name TEXT,\n  object_name TEXT,\n  description TEXT,\n  created_at TIMESTAMPTZ,\n  created_by TEXT,\n  last_modified TIMESTAMPTZ,\n  PRIMARY KEY (object_type, schema_name, object_name)\n);\n\nCREATE FUNCTION update_dictionary()\nRETURNS event_trigger AS $$\nDECLARE\n  obj RECORD;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    INSERT INTO data_dictionary(\n      object_type, schema_name, object_name,\n      created_at, created_by, last_modified\n    ) VALUES (\n      obj.object_type, obj.schema_name,\n      split_part(obj.object_identity, '.', 2),\n      now(), current_user, now()\n    )\n    ON CONFLICT (object_type, schema_name, object_name)\n    DO UPDATE SET last_modified = now();\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER sync_dictionary\n  ON ddl_command_end\n  EXECUTE FUNCTION update_dictionary();", tags: ['advanced', 'event-triggers', 'data-dictionary', 'metadata'] },
  { id: 'pg-advanced-l3-086', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'Custom Aggregates', question: 'How do you create an aggregate with a polymorphic return type?', options: ['Aggregates always return the same type as input', 'Use anyelement and anyarray polymorphic types in the aggregate definition — this allows creating a single aggregate that works with multiple input types, with PostgreSQL resolving the actual types at call time based on the input arguments', 'Polymorphic aggregates are not supported', 'Create overloaded aggregates for each type'], correctAnswer: 1, explanation: 'PostgreSQL polymorphic types (anyelement, anyarray, anycompatible) allow creating type-generic aggregates. The actual types are resolved at query time based on the input. The sfunc, ffunc, and state type can all use polymorphic types. This avoids creating separate aggregates for INTEGER, NUMERIC, FLOAT, etc. The type system ensures type safety at compile time while providing generality.', codeSnippet: "-- Polymorphic first/last aggregate:\nCREATE FUNCTION first_sfunc(\n  state anyelement, val anyelement\n) RETURNS anyelement AS $$\nBEGIN\n  IF state IS NULL THEN RETURN val; END IF;\n  RETURN state;  -- keep first value\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE first(anyelement) (\n  sfunc = first_sfunc,\n  stype = anyelement\n);\n\n-- Works with any type:\nSELECT first(name) FROM users ORDER BY created_at;\nSELECT first(price) FROM products ORDER BY id;\nSELECT first(created_at) FROM events;\n\n-- Polymorphic last value:\nCREATE FUNCTION last_sfunc(\n  state anyelement, val anyelement\n) RETURNS anyelement AS $$\nBEGIN\n  RETURN val;  -- always replace with latest\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE AGGREGATE last(anyelement) (\n  sfunc = last_sfunc,\n  stype = anyelement\n);", tags: ['advanced', 'custom-aggregates', 'polymorphic', 'anyelement'] },
  { id: 'pg-advanced-l3-087', language: 'postgresql', level: 'level3', category: 'Advanced', subcategory: 'PostGIS', question: 'How do you use PostGIS for temporal-spatial queries combining time and location?', options: ['PostGIS does not support temporal data', 'Store timestamps alongside geometries and filter on both dimensions — combine spatial predicates (ST_DWithin, ST_Contains) with temporal conditions (BETWEEN, date ranges) to answer questions like "which events occurred within 1km of this point last week"', 'Use a separate time-series database', 'Temporal-spatial queries require specialized databases'], correctAnswer: 2, explanation: 'Temporal-spatial (spatio-temporal) queries combine WHERE clauses on spatial and temporal columns. For efficient indexing, create both a spatial GiST index on the geometry column and a B-tree (or BRIN) index on the timestamp column. For frequent combined queries, a composite GiST index using btree_gist extension can index both geometry and timestamp together, enabling efficient two-dimensional filtering.', codeSnippet: "-- Create table with spatial + temporal:\nCREATE TABLE incidents (\n  id SERIAL PRIMARY KEY,\n  location GEOMETRY(Point, 4326),\n  occurred_at TIMESTAMPTZ,\n  type TEXT,\n  description TEXT\n);\n\n-- Spatial + temporal indexes:\nCREATE INDEX idx_incident_loc\n  ON incidents USING gist (location);\nCREATE INDEX idx_incident_time\n  ON incidents (occurred_at);\n\n-- Composite index (requires btree_gist):\nCREATE EXTENSION btree_gist;\nCREATE INDEX idx_incident_spacetime\n  ON incidents USING gist (location, occurred_at);\n\n-- Spatio-temporal query:\nSELECT *\nFROM incidents\nWHERE ST_DWithin(\n  location::geography,\n  ST_MakePoint(-73.985, 40.748)::geography,\n  500  -- 500 meters\n)\nAND occurred_at BETWEEN '2024-01-01' AND '2024-01-31'\nAND type = 'theft';", tags: ['advanced', 'postgis', 'spatio-temporal', 'time-location'] },
];

export default questions;
